    // e2f1222-TC-001
    @Test
    public void updateExistingItemStatusAndVerifyChange() {
        String itemName = "Formal Shirt_" + System.currentTimeMillis();
        String createBody = """
            {
              "nameEn": "%s",
              "nameBn": "?? ?????",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Collar",
                  "nameBn": "????",
                  "unit": "in",
                  "type": "TEXT"
                }
              ]
            }
            """.formatted(itemName);
        Response createResp = given().contentType(ContentType.JSON).body(createBody).when().post("/api/items").then().statusCode(200).extract().response();
        Integer itemId = createResp.path("data.id");
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no ID");
        String updateBody = """
            {
              "nameEn": "%s",
              "nameBn": "?? ?????",
              "status": "INACTIVE",
              "parameters": [
                {
                  "nameEn": "Collar",
                  "nameBn": "????",
                  "unit": "in",
                  "type": "TEXT"
                }
              ]
            }
            """.formatted(itemName);
        given().contentType(ContentType.JSON).body(updateBody).when().put("/api/items/{id}", itemId).then().statusCode(200).body("data.status", equalTo("INACTIVE")).body("data.nameEn", equalTo(itemName));
        given().when().get("/api/items/{id}", itemId).then().statusCode(200).body("data.status", equalTo("INACTIVE")).body("data.nameEn", equalTo(itemName)).body("data.parameters", hasSize(1));
    }

