    // e2f1222-TC-028
    @Test
    public void createMeasuringParameterWithDuplicateNameForSameItem() {
        long timestamp = System.currentTimeMillis();
        String initialItemPayload = """
            {
              "nameEn": "Item_%d",
              "nameBn": "Item_BN_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest Width",
                  "nameBn": "Chest Width BN",
                  "unit": "inch",
                  "type": "NUMBER",
                  "suggestiveValues": ["38", "40", "42"],
                  "nsId": "ns_1"
                }
              ]
            }
            """.formatted(timestamp, timestamp);
        Response createRes = given().contentType(ContentType.JSON).body(initialItemPayload).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object itemIdObj = createRes.path("data.id") != null ? createRes.path("data.id") : createRes.path("id");
        Assert.assertNotNull(itemIdObj, "Precondition failed: Item creation returned no ID");
        long itemId = ((Number) itemIdObj).longValue();
        String duplicateParamPayload = """
            {
              "nameEn": "Item_%d",
              "nameBn": "Item_BN_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest Width",
                  "nameBn": "Chest Width BN 1",
                  "unit": "inch",
                  "type": "NUMBER",
                  "suggestiveValues": ["38"],
                  "nsId": "ns_1"
                },
                {
                  "nameEn": "Chest Width",
                  "nameBn": "Chest Width BN 2",
                  "unit": "inch",
                  "type": "NUMBER",
                  "suggestiveValues": ["40"],
                  "nsId": "ns_2"
                }
              ]
            }
            """.formatted(timestamp, timestamp);
        given().contentType(ContentType.JSON).body(duplicateParamPayload).when().put("/api/items/{id}", itemId).then().statusCode(anyOf(is(400), is(409), is(422)));
    }

