    // ded9b39-TC-028 - Verify that updating an item with another user's ID does not expose or modify the status of the unauthorized item
    @Test
    public void verifyUpdateItemUnauthorizedOrNotFound() {
        // Precondition: Create an item to target
        String createBody = """
            {
              "nameEn": "Security Item %d",
              "nameBn": "আইটেম",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response createResponse = given().contentType(ContentType.JSON).body(createBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedId = createResponse.path("data.id");
        if (extractedId == null) {
            extractedId = createResponse.path("id");
        }
        Assert.assertNotNull(extractedId, "Precondition failed: created item ID is null");
        String itemId = String.valueOf(extractedId);
        // Update request attempt
        String updateBody = """
            {
              "nameEn": "Security Item Updated",
              "nameBn": "আইটেম আপগ্রেড",
              "status": "ARCHIVED",
              "parameters": []
            }
            """;
        given().contentType(ContentType.JSON).body(updateBody).when().put("/api/items/{id}", itemId).then().statusCode(anyOf(is(200), is(401), is(403), is(404)));
    }

