    // ded9b39-TC-030 - Verify that item creation and update enforce rate limiting to prevent abuse
    @Test
    public void verifyRateLimitingOnItemCreation() {
        String payload = """
            {
              "nameEn": "Rate Limit Test %d",
              "nameBn": "টেস্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "unit": "cm"
                }
              ]
            }
            """.formatted(System.currentTimeMillis());
        int lastStatusCode = 200;
        for (int i = 0; i < 20; i++) {
            Response response = given().contentType(ContentType.JSON).body(payload).when().post("/api/items");
            lastStatusCode = response.getStatusCode();
        }
        Assert.assertTrue(lastStatusCode == 200 || lastStatusCode == 201 || lastStatusCode == 429, "Expected status code 200/201 or 429 for rate limit test, got: " + lastStatusCode);
    }

