    // 226f7f9-TC-002
    @Test
    public void retrieveAllShops() {
        // 1. Setup Precondition: Create an Area
        String areaName = "Area_%d".formatted(System.currentTimeMillis());
        String createAreaPayload = """
            {
              "name": "%s"
            }
            """.formatted(areaName);
        Response areaResp = given().contentType(ContentType.JSON).body(createAreaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedAreaId = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(extractedAreaId, "Precondition failed: Area creation returned null ID");
        long areaId = ((Number) extractedAreaId).longValue();
        // 2. Setup Precondition: Create a Shop under the created Area
        String shopName = "Shop_%d".formatted(System.currentTimeMillis());
        String createShopPayload = """
            {
              "shopName": "%s",
              "shopPhone": "01700000000",
              "latitude": 23.8103,
              "longitude": 90.4125,
              "ownerName": "Owner",
              "email": "owner_%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(shopName, System.currentTimeMillis(), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(createShopPayload).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedShopId = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(extractedShopId, "Precondition failed: Shop creation returned null ID");
        // 3. Perform Test Case Assertion: GET /api/areas/{areaId}/shops with pagination parameters
        given().pathParam("areaId", areaId).queryParam("page", 0).queryParam("limit", 10).when().get("/api/areas/{areaId}/shops").then().statusCode(200).body("status", equalTo("success")).body("data.content", not(empty()));
    }

    // 226f7f9-TC-003
    @Test
    public void updateExistingShop() {
        // Step 1: Create an area for precondition
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResponse = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedAreaId = areaResponse.path("data.id");
        if (extractedAreaId == null) {
            extractedAreaId = areaResponse.path("id");
        }
        Assert.assertNotNull(extractedAreaId, "Precondition failed: Area creation returned no id");
        Long areaId = Long.valueOf(extractedAreaId.toString());
        // Step 2: Create a shop under the created area for precondition
        String createShopBody = """
            {
              "shopName": "Initial Shop %d",
              "shopPhone": "017%d",
              "ownerName": "Owner Name",
              "email": "shop_%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), areaId);
        Response shopResponse = given().contentType(ContentType.JSON).body(createShopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedShopId = shopResponse.path("data.id");
        if (extractedShopId == null) {
            extractedShopId = shopResponse.path("id");
        }
        Assert.assertNotNull(extractedShopId, "Precondition failed: Shop creation returned no id");
        Long shopId = Long.valueOf(extractedShopId.toString());
        // Step 3: Execute the update shop test case
        String updatedShopName = "Updated Shop Name " + System.currentTimeMillis();
        String updateShopBody = """
            {
              "shopName": "%s",
              "shopPhone": "017%d",
              "ownerName": "Owner Name",
              "email": "shop_%d@example.com",
              "address": "Updated Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(updatedShopName, System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), areaId);
        given().contentType(ContentType.JSON).body(updateShopBody).when().put("/api/areas/{areaId}/shops/{id}", areaId, shopId).then().statusCode(200).body("data.shopName", equalTo(updatedShopName));
    }

