    // 226f7f9-TC-031
    @Test
    public void verifyOtpVerificationEnforcesRateLimitingToPreventBruteForceAttacks() {
        String phoneNumber = "+12345%d".formatted(System.currentTimeMillis() % 100000);
        for (int i = 0; i < 10; i++) {
            String payload = """
                {
                  "phoneNumber": "%s",
                  "otp": "%04d"
                }
                """.formatted(phoneNumber, i);
            given().contentType(ContentType.JSON).body(payload).when().post("/api/auth/verify-otp");
        }
        String validPayload = """
            {
              "phoneNumber": "%s",
              "otp": "1234"
            }
            """.formatted(phoneNumber);
        given().contentType(ContentType.JSON).body(validPayload).when().post("/api/auth/verify-otp").then().statusCode(429);
    }

