    // d9f8e47-TC-007
    @Test
    public void updateOrderWithInvalidCustomerPhotoFormat() {
        // Step 1: Create an Area as a precondition fixture
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no id");
        // Step 2: Create a Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no id");
        // Step 3: Create an Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no id");
        // Step 4: Create an Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, System.currentTimeMillis() % 100000000L, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long orderNumericId = orderResp.path("data.id") != null ? ((Number) orderResp.path("data.id")).longValue() : (orderResp.path("id") != null ? ((Number) orderResp.path("id")).longValue() : null);
        Assert.assertNotNull(orderNumericId, "Precondition failed: Order creation returned no id");
        // Step 5: Send PUT with invalid customerPhoto format
        String updateBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "customerPhoto": "invalid-base64-string",
              "paidAmount": 100.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, System.currentTimeMillis() % 100000000L, itemId);
        given().contentType(ContentType.JSON).body(updateBody).when().put("/api/orders/{orderId}", orderNumericId).then().statusCode(anyOf(is(400), is(403), is(422)));
    }

