    // Helper method to create prerequisite Area, Shop, and Item
    private Prereqs createPrerequisites() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number areaIdNum = areaResp.path("data.id");
        if (areaIdNum == null)
            areaIdNum = areaResp.path("id");
        Assert.assertNotNull(areaIdNum, "Precondition failed: Area creation returned no ID");
        Long areaId = areaIdNum.longValue();
        // 2. Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shopIdNum = shopResp.path("data.id");
        if (shopIdNum == null)
            shopIdNum = shopResp.path("id");
        Assert.assertNotNull(shopIdNum, "Precondition failed: Shop creation returned no ID");
        Long shopId = shopIdNum.longValue();
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "Shirt",
              "status": "ACTIVE"
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number itemIdNum = itemResp.path("data.id");
        if (itemIdNum == null)
            itemIdNum = itemResp.path("id");
        Assert.assertNotNull(itemIdNum, "Precondition failed: Item creation returned no ID");
        Long itemId = itemIdNum.longValue();
        return new Prereqs(shopId, itemId);
    }

    private static class Prereqs {

        final Long shopId;

        final Long itemId;

        Prereqs(Long shopId, Long itemId) {
            this.shopId = shopId;
            this.itemId = itemId;
        }
    }

