        Long shopId = shopResponse.path("data.id") != null ? ((Number) shopResponse.path("data.id")).longValue() : ((Number) shopResponse.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no ID");
        // 3. Create Item
