    private Object[] setupOrderPrerequisites(String photoUrl) {
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Number areaIdNum = areaResp.path("data.id");
        Assert.assertNotNull(areaIdNum, "Precondition failed: Area creation failed");
        long areaId = areaIdNum.longValue();
        // 2. Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), (int) (Math.random() * 100000000), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(200).extract().response();
        Number shopIdNum = shopResp.path("id") != null ? shopResp.path("id") : shopResp.path("data.id");
        Assert.assertNotNull(shopIdNum, "Precondition failed: Shop creation failed");
        long shopId = shopIdNum.longValue();
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Item_%d",
              "nameBn": "আইটেম",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Number itemIdNum = itemResp.path("data.id");
        Assert.assertNotNull(itemIdNum, "Precondition failed: Item creation failed");
        long itemId = itemIdNum.longValue();
        // 4. Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2025-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "measurementClothPhoto": "%s",
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, (int) (Math.random() * 100000000), itemId, photoUrl);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        String businessOrderId = orderResp.path("data.orderId");
        Assert.assertNotNull(businessOrderId, "Precondition failed: Order creation failed to return orderId");
        Number numericOrderIdNum = orderResp.path("data.id");
        return new Object[] { businessOrderId, numericOrderIdNum != null ? numericOrderIdNum.longValue() : null };
    }

