    // Test Case: 9f19f61-TC-018 - Create an order and verify the default status is set to 'MEASUREMENT_DONE'
    @Test
    public void createOrderAndVerifyDefaultStatus() {
        // Precondition: Create an item first
        String itemBody = """
            {
              "nameEn": "Shirt",\n              "nameBn": "শার্ট",\n              "status": "ACTIVE",\n              "parameters": []
            }
            """;
        Integer itemId = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Assert.assertNotNull(itemId, "Precondition failed: no item id returned");
        // Precondition: Create a shop
        String shopBody = """
            {
              "shopName": "Test Shop",\n              "shopPhone": "+1234567890",\n              "latitude": 23.8103,\n              "longitude": 90.4125,\n              "ownerName": "Test Owner",\n              "email": "test@example.com",\n              "address": "Test Address",\n              "areaId": 1,\n              "status": true
            }
            """;
        Integer shopId = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/shops").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Assert.assertNotNull(shopId, "Precondition failed: no shop id returned");
        // Create order
        String orderBody = """
            {
              "customerName": "John Doe",\n              "customerPhone": "1234567890",\n              "customerGender": "MALE",\n              "paidAmount": 1000,\n              "deliveryDate": "2023-12-15",\n              "shopId": %d,\n              "items": [{
                "itemId": %d,\n                "measurementGroups": []
              }]
            }
            """.formatted(shopId, itemId);
        Response createResponse = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId = createResponse.path("data.id").toString();
        Assert.assertNotNull(orderId, "Precondition failed: no order id returned");
        // Verify default status is MEASUREMENT_DONE
        given().contentType(ContentType.JSON).when().get("/api/orders/{id}", orderId).then().statusCode(200).body("data.status", equalTo("MEASUREMENT_DONE"));
    }

