    // Test Case: 9f19f61-TC-020 - Retrieve an order with multiple items of the same type and verify item count aggregation
    @Test
    public void retrieveOrderWithItemCountAggregation() {
        // Precondition: Create items
        String shirtItemBody = """
            {
              "nameEn": "Shirt",\n              "nameBn": "শার্ট",\n              "status": "ACTIVE",\n              "parameters": []
            }
            """;
        Integer shirtItemId = given().contentType(ContentType.JSON).body(shirtItemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Assert.assertNotNull(shirtItemId, "Precondition failed: no shirt item id returned");
        String pantItemBody = """
            {
              "nameEn": "Pant",\n              "nameBn": "প্যান্ট",\n              "status": "ACTIVE",\n              "parameters": []
            }
            """;
        Integer pantItemId = given().contentType(ContentType.JSON).body(pantItemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Assert.assertNotNull(pantItemId, "Precondition failed: no pant item id returned");
        // Precondition: Create a shop
        String shopBody = """
            {
              "shopName": "Aggregation Test Shop",\n              "shopPhone": "+1234567892",\n              "latitude": 23.8103,\n              "longitude": 90.4125,\n              "ownerName": "Test Owner",\n              "email": "aggregation@example.com",\n              "address": "Test Address",\n              "areaId": 1,\n              "status": true
            }
            """;
        Integer shopId = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/shops").then().statusCode(anyOf(is(200), is(201))).extract().path("data.id");
        Assert.assertNotNull(shopId, "Precondition failed: no shop id returned");
        // Create order with 3 shirts and 2 pants
        String orderBody = """
            {
              "customerName": "Test Customer",\n              "customerPhone": "1234567893",\n              "customerGender": "MALE",\n              "paidAmount": 5000,\n              "deliveryDate": "2023-12-20",\n              "shopId": %d,\n              "items": [{
                "itemId": %d,\n                "measurementGroups": []
              }, {
                "itemId": %d,\n                "measurementGroups": []
              }, {
                "itemId": %d,\n                "measurementGroups": []
              }, {
                "itemId": %d,\n                "measurementGroups": []
              }, {
                "itemId": %d,\n                "measurementGroups": []
              }]
            }
            """.formatted(shopId, shirtItemId, shirtItemId, shirtItemId, pantItemId, pantItemId);
        Response createResponse = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId = createResponse.path("data.id").toString();
        Assert.assertNotNull(orderId, "Precondition failed: no order id returned");
        // Verify item count aggregation
        given().contentType(ContentType.JSON).when().get("/api/orders/{id}", orderId).then().statusCode(200).body("data.items.itemName", hasItems("Shirt", "Pant")).body("data.items.count", hasItems(greaterThan(0), greaterThan(0)));
    }

