    // 9e5d511-TC-003 - Attempt to update order item status with invalid transition (e.g., MEASUREMENT_DONE to PRESS_DONE)
    @Test
    public void testUpdateOrderItemStatusInvalidTransition() {
        // Setup: Create an area
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer areaId = areaResp.path("data.id");
        if (areaId == null) {
            areaId = areaResp.path("id");
        }
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no id");
        // Setup: Create a shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer shopId = shopResp.path("data.id");
        if (shopId == null) {
            shopId = shopResp.path("id");
        }
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no id");
        // Setup: Create an item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer itemId = itemResp.path("data.id");
        if (itemId == null) {
            itemId = itemResp.path("id");
        }
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no id");
        // Setup: Create an order containing an order item
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp % 100000000L, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer orderItemId = orderResp.path("data.items[0].id");
        if (orderItemId == null) {
            orderItemId = orderResp.path("data.orderItems[0].id");
        }
        if (orderItemId == null) {
            orderItemId = orderResp.path("items[0].id");
        }
        Assert.assertNotNull(orderItemId, "Precondition failed: Order creation returned no orderItemId");
        // Act & Assert: Attempt to update order item status with invalid transition
        String updateStatusBody = """
            {
              "newStatus": "PRESS_DONE"
            }
            """;
        given().contentType(ContentType.JSON).body(updateStatusBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(400);
    }

