    // d3da340-TC-005
    @Test
    public void updateOrderStatus() {
        long timestamp = System.currentTimeMillis();
        // 1. Precondition: Create Area
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : null;
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no ID");
        // 2. Precondition: Create Shop
        String shopBody = """
            {
              "shopName": "Test Shop %d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, (int) (timestamp % 100000000L), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("id") != null ? ((Number) shopResp.path("id")).longValue() : (shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : null);
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no ID");
        // 3. Precondition: Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "Shirt",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : null;
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no ID");
        // 4. Precondition: Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, (int) (timestamp % 100000000L), itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long orderItemId = orderResp.path("data.items[0].id") != null ? ((Number) orderResp.path("data.items[0].id")).longValue() : (orderResp.path("data.id") != null ? ((Number) orderResp.path("data.id")).longValue() : null);
        Assert.assertNotNull(orderItemId, "Precondition failed: Order creation returned no item/order ID");
        // 5. Test Step: Update Order Item Status
        String updateStatusBody = """
            {
              "newStatus": "CUTTING_DONE"
            }
            """;
        given().contentType(ContentType.JSON).body(updateStatusBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200).body("status", equalTo("success")).body("message", containsString("updated successfully"));
    }

