    /**
     * Helper method to create an area.
     */
    private Long createArea() {
        String areaPayload = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response resp = given().contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long id = resp.path("data.id") != null ? resp.path("data.id") : resp.path("id");
        Assert.assertNotNull(id, "Precondition failed: Area creation returned null ID");
        return id;
    }

    /**
     * Helper method to create a shop under an area.
     */
    private Long createShop(Long areaId) {
        String shopPayload = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response resp = given().contentType(ContentType.JSON).body(shopPayload).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long id = resp.path("data.id") != null ? resp.path("data.id") : resp.path("id");
        if (id == null) {
            // Shop controller might return raw Shop object
            Number numId = resp.path("id");
            if (numId != null)
                id = numId.longValue();
        }
        Assert.assertNotNull(id, "Precondition failed: Shop creation returned null ID");
        return id;
    }

    /**
     * Helper method to create an item.
     */
    private Long createItem() {
        String itemPayload = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "Shirt_BN",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response resp = given().contentType(ContentType.JSON).body(itemPayload).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long id = resp.path("data.id") != null ? resp.path("data.id") : resp.path("id");
        Assert.assertNotNull(id, "Precondition failed: Item creation returned null ID");
        return id;
    }

    /**
     * Helper method to create an order.
     */
    private Number createOrder(Long shopId, Long itemId) {
        String orderPayload = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "12345678901",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2025-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response resp = given().contentType(ContentType.JSON).body(orderPayload).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number orderId = resp.path("data.id") != null ? resp.path("data.id") : resp.path("id");
        Assert.assertNotNull(orderId, "Precondition failed: Order creation returned null ID");
        return orderId;
    }

