        Response shopResponse = given().contentType(ContentType.JSON).body(shopPayload).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResponse.path("data.id") != null ? shopResponse.path("data.id") : shopResponse.path("id");
        Assert.assertNotNull(shopIdObj, "Precondition failed: Shop creation returned no ID");
