    // 113f2a9-TC-004
    @Test
    public void updateOrderItemStatusToReadyForDelivery() {
        // 1. Setup prerequisite Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // 2. Setup prerequisite Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%d",
              "areaId": %d
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop ID is null");
        // 3. Setup prerequisite Item
        String itemBody = """
            {
              "nameEn": "Trousers_%d",
              "nameBn": "ট্যাজার",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item ID is null");
        // 4. Setup Order with item
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "018%d",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, System.currentTimeMillis() % 100000000L, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String orderBusinessId = orderResp.path("data.orderId") != null ? orderResp.path("data.orderId").toString() : orderResp.path("data.id").toString();
        Assert.assertNotNull(orderBusinessId, "Precondition failed: Order ID is null");
        // Retrieve Order details to extract orderItemId
        Response getOrderResp = given().when().get("/api/orders/{orderId}", orderBusinessId).then().statusCode(200).extract().response();
        Long orderItemId = getOrderResp.path("data.items[0].id") != null ? ((Number) getOrderResp.path("data.items[0].id")).longValue() : ((Number) getOrderResp.path("items[0].id")).longValue();
        Assert.assertNotNull(orderItemId, "Precondition failed: Order Item ID is null");
        // Set initial status to SEWING_DONE as per precondition
        String setSewingDoneBody = """
            {
              "newStatus": "SEWING_DONE"
            }
            """;
        given().contentType(ContentType.JSON).body(setSewingDoneBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200);
        // Execute update status to READY_FOR_DELIVERY
        String updateBody = """
            {
              "newStatus": "READY_FOR_DELIVERY"
            }
            """;
        given().contentType(ContentType.JSON).body(updateBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200).body("status", equalTo("success"));
        // Verify in order details
        given().when().get("/api/orders/{orderId}", orderBusinessId).then().statusCode(200).body("data.items[0].status", equalTo("READY_FOR_DELIVERY"));
    }

