        Long shopId = ((Number) rawShopId).longValue();
        // 3. Create Item precondition
        String itemBody = """
            {
              "nameEn": "Item_%d",
              "nameBn": "Item",
              "status": "ACTIVE"
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object rawItemId = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(rawItemId, "Precondition failed: Item creation returned no ID");
        Long itemId = ((Number) rawItemId).longValue();
