        Object rawOrderItemId = orderResp.path("data.items[0].id") != null ? orderResp.path("data.items[0].id") : orderResp.path("data.id");
        Assert.assertNotNull(rawOrderItemId, "Precondition failed: Order creation returned no order item ID");
        Long orderItemId = ((Number) rawOrderItemId).longValue();
        // 5. Update status to final status 'DELIVERED'
