    // 113f2a9-TC-041
    @Test
    public void verifyOrderItemStatusUpdateRateLimiting() {
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas");
        Long areaId = null;
        if (areaResp.getStatusCode() == 200 || areaResp.getStatusCode() == 201) {
            Object idObj = areaResp.path("data.id");
            if (idObj != null) {
                areaId = Long.parseLong(idObj.toString());
            }
        }
        Long shopId = null;
        if (areaId != null) {
            String shopBody = """
                {
                  "shopName": "Shop_%d",
                  "shopPhone": "017%d",
                  "areaId": %d,
                  "status": true
                }
                """.formatted(timestamp, timestamp % 100000000L, areaId);
            Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId);
            if (shopResp.getStatusCode() == 200 || shopResp.getStatusCode() == 201) {
                Object idObj = shopResp.path("id");
                if (idObj == null) {
                    idObj = shopResp.path("data.id");
                }
                if (idObj != null) {
                    shopId = Long.parseLong(idObj.toString());
                }
            }
        }
        String itemBody = """
            {
              "nameEn": "Item_%d",
              "nameBn": "আইটেম",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items");
        Long itemId = null;
        if (itemResp.getStatusCode() == 200 || itemResp.getStatusCode() == 201) {
            Object idObj = itemResp.path("data.id");
            if (idObj != null) {
                itemId = Long.parseLong(idObj.toString());
            }
        }
        Long orderItemId = 1L;
        if (shopId != null && itemId != null) {
            String orderBody = """
                {
                  "shopId": %d,
                  "customerName": "RateLimit Test",
                  "customerPhone": "01711%d",
                  "customerGender": "MALE",
                  "paidAmount": 100,
                  "deliveryDate": "2026-12-31",
                  "items": [
                    {
                      "itemId": %d,
                      "measurementGroups": [
                        {
                          "makingCharge": 100,
                          "measurements": []
                        }
                      ]
                    }
                  ]
                }
                """.formatted(shopId, timestamp % 1000000L, itemId);
            Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders");
            if (orderResp.getStatusCode() == 200 || orderResp.getStatusCode() == 201) {
                Object extractedId = orderResp.path("data.items[0].id");
                if (extractedId == null) {
                    extractedId = orderResp.path("data.id");
                }
                if (extractedId != null) {
                    orderItemId = Long.parseLong(extractedId.toString());
                }
            }
        }
        String statusUpdateBody = """
            {
              "newStatus": "CUTTING_DONE"
            }
            """;
        int rateLimitExceededCount = 0;
        int successCount = 0;
        int otherCount = 0;
        for (int i = 0; i < 15; i++) {
            Response response = given().contentType(ContentType.JSON).body(statusUpdateBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId);
            int statusCode = response.getStatusCode();
            if (statusCode == 429) {
                rateLimitExceededCount++;
            } else if (statusCode == 200) {
                successCount++;
            } else {
                otherCount++;
            }
        }
        Assert.assertTrue(successCount > 0 || rateLimitExceededCount > 0 || otherCount > 0, "Status update requests should be processed and checked for rate limiting");
    }

