    // 45ca61c-TC-007
    @Test
    public void verifyOrderRetrievalDoesNotExposeInternalDatabaseIds() {
        // 1. Setup precondition: Create an Area
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // 2. Setup precondition: Create a Shop
        String shopBody = """
            {
              "shopName": "Test Shop %d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), (int) (Math.random() * 100000000), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop ID is null");
        // 3. Setup precondition: Create an Item
        String itemBody = """
            {
              "nameEn": "Shirt %d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item ID is null");
        // 4. Setup precondition: Create an Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 500,
              "deliveryDate": "2025-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, (int) (Math.random() * 100000000), itemId);
        Response createOrderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String orderIdCode = createOrderResp.path("data.orderId");
        Assert.assertNotNull(orderIdCode, "Precondition failed: Order string orderId was not returned");
        // 5. Execute GET request to retrieve order by orderId
        Response getOrderResp = given().contentType(ContentType.JSON).when().get("/api/orders/{orderId}", orderIdCode).then().statusCode(200).body("status", equalTo("success")).body("data.orderId", equalTo(orderIdCode)).extract().response();
        // Verify internal database ID (numeric primary key) is not exposed in root data object
        Assert.assertNull(getOrderResp.path("data.id"), "Internal database ID 'data.id' should not be exposed");
    }

