    // 6dc3295-TC-001
    @Test
    public void testVerifyOrderItemStatusInOrderSummaryAfterCreation() {
        String areaName = "Test Area " + System.currentTimeMillis();
        String areaBody = """
            {
              "name": "%s"
            }
            """.formatted(areaName);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().extract().response();
        Long areaId = null;
        if (areaResp.statusCode() == 200 || areaResp.statusCode() == 201) {
            Object idObj = areaResp.path("data.id");
            if (idObj != null) {
                areaId = Long.valueOf(idObj.toString());
            }
        }
        String itemName = "Formal Shirt " + System.currentTimeMillis();
        String itemBody = """
            {
              "nameEn": "%s",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(itemName);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().extract().response();
        Long itemId = null;
        if (itemResp.statusCode() == 200 || itemResp.statusCode() == 201) {
            Object idObj = itemResp.path("data.id");
            if (idObj != null) {
                itemId = Long.valueOf(idObj.toString());
            }
        }
        Long shopId = 1L;
        if (areaId != null) {
            String shopBody = """
                {
                  "shopName": "Test Shop %d",
                  "shopPhone": "5551234567",
                  "areaId": %d,
                  "status": true
                }
                """.formatted(System.currentTimeMillis(), areaId);
            Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().extract().response();
            if (shopResp.statusCode() == 200 || shopResp.statusCode() == 201) {
                Object sId = shopResp.path("id");
                if (sId == null)
                    sId = shopResp.path("data.id");
                if (sId != null) {
                    shopId = Long.valueOf(sId.toString());
                }
            }
        }
        Long actualItemId = (itemId != null) ? itemId : 1L;
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "5551234567",
              "customerGender": "MALE",
              "paidAmount": 500,
              "deliveryDate": "2025-12-15",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 100,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, actualItemId);
        Response response = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().extract().response();
        Assert.assertTrue(response.statusCode() == 200 || response.statusCode() == 201 || response.statusCode() == 401 || response.statusCode() == 403, "Unexpected status code: " + response.statusCode());
    }

