    // 6dc3295-TC-013 - Verify that order item status is exposed in order responses only for authorized users
    @Test
    public void verifyOrderItemStatusExposedForAuthorizedUser() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number areaIdNum = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdNum, "Precondition failed: Area creation returned null id");
        long areaId = areaIdNum.longValue();
        // 2. Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d
            }
            """.formatted(timestamp, timestamp % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shopIdNum = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(shopIdNum, "Precondition failed: Shop creation returned null id");
        long shopId = shopIdNum.longValue();
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট_%d",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp, timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number itemIdNum = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemIdNum, "Precondition failed: Item creation returned null id");
        long itemId = itemIdNum.longValue();
        // 4. Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer_%d",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2030-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 50.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp, timestamp % 100000000L, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String orderIdStr = orderResp.path("data.orderId") != null ? orderResp.path("data.orderId").toString() : (orderResp.path("data.id") != null ? orderResp.path("data.id").toString() : null);
        Assert.assertNotNull(orderIdStr, "Precondition failed: Order creation returned null orderId");
        // Perform target API request to retrieve order details
        given().when().get("/api/orders/{orderId}", orderIdStr).then().statusCode(200).body("status", equalTo("success")).body("data", notNullValue());
    }

