    // 6dc3295-TC-015
    @Test
    public void verifyOrderItemStatusNotLeakedInErrorMessages() {
        // Step 1 & 2: Attempt to update status of a non-existent order item ID (e.g. 999999)
        String payload = """
            {
              "newStatus": "SEWING_DONE"
            }
            """;
        // Step 3 & 4: Execute PUT and check error response
        Response response = given().contentType(ContentType.JSON).body(payload).when().put("/api/orders/items/{orderItemId}/status", 999999L).then().statusCode(anyOf(is(400), is(404), is(500))).extract().response();
        String responseBody = response.asString().toLowerCase();
        // Assert internal details / stack traces are not exposed
        Assert.assertFalse(responseBody.contains("exception"), "Response body should not contain raw exception class names: " + responseBody);
        Assert.assertFalse(responseBody.contains("sql"), "Response body should not contain raw SQL/database error details: " + responseBody);
        Assert.assertFalse(responseBody.contains("stacktrace"), "Response body should not contain stack traces: " + responseBody);
    }

