    // 313179b-TC-008 - Retrieve last measurement for an item with numeric value at minimum allowed (0.0)
    @Test
    public void getLastMeasurementMinimumNumericValue() {
        // Precondition setup: Area & Shop
        String areaPayload = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no id");
        String shopPhone = "017%08d".formatted(System.currentTimeMillis() % 100000000L);
        String shopPayload = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "%s",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), shopPhone, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopPayload).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no id");
        // Precondition setup: Item
        String itemPayload = """
            {
              "nameEn": "Pant_%d",
              "nameBn": "প্যান্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemPayload).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no id");
        // Create Order with numeric measurement value 0.0
        String customerPhone = "1234567890";
        String orderPayload = """
            {
              "shopId": %d,
              "customerName": "Jane Doe",
              "customerPhone": "%s",
              "customerGender": "FEMALE",
              "paidAmount": 0,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 50,
                      "measurements": [
                        {
                          "nameEn": "Waist",
                          "nameBn": "কোমর",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": 0.0
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, customerPhone, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderPayload).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long customerId = orderResp.path("data.customerId") != null ? ((Number) orderResp.path("data.customerId")).longValue() : null;
        if (customerId == null) {
            // Fallback: try reading customer via customer endpoint if not present directly
            Response custResp = given().queryParam("phone", customerPhone).when().get("/api/customers/by-phone").then().statusCode(200).extract().response();
            customerId = custResp.path("data[0].id") != null ? ((Number) custResp.path("data[0].id")).longValue() : 1L;
        }
        // Perform the request under test
        Response response = given().queryParam("phone", customerPhone).queryParam("customerId", customerId).queryParam("itemId", itemId).when().get("/api/orders/last-measurement").then().statusCode(200).body("data.measurements", notNullValue()).extract().response();
        Number val = response.path("data.measurements[0].value");
        Assert.assertNotNull(val, "Measurement value should not be null");
        Assert.assertEquals(val.doubleValue(), 0.0, 0.001, "Numeric value should be 0.0");
    }

