    // 313179b-TC-019
    @Test
    public void retrieveLastMeasurementForAnItemWithAUnitAtMaximumAllowedLength() {
        String uniqueName = "Area_" + System.currentTimeMillis();
        String areaBody = """
            {
              "name": "%s"
            }
            """.formatted(uniqueName);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation failed");
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation failed");
        String maxLengthUnit = "u".repeat(50);
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "চেস্ট",
                  "unit": "%s",
                  "type": "TEXT"
                }
              ]
            }
            """.formatted(System.currentTimeMillis(), maxLengthUnit);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item creation failed");
        String phone = "1234567890";
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.00,
                      "measurements": [
                        {
                          "parameterId": 1,
                          "value": "40"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, phone, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long customerId = orderResp.path("data.customerId") != null ? ((Number) orderResp.path("data.customerId")).longValue() : 1L;
        given().queryParam("phone", phone).queryParam("customerId", customerId).queryParam("itemId", itemId).when().get("/api/orders/last-measurement").then().statusCode(200).body("data.measurements[0].unit", equalTo(maxLengthUnit));
    }

