    // 3c1bbe1-TC-003
    @Test
    public void verifyOrderIdsGeneratedSequentiallyAndUniquely() {
        long timestamp = System.currentTimeMillis();
        // Step 1: Create Area precondition
        String areaPayload = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResponse = given().contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdVal = areaResponse.path("data.id") != null ? areaResponse.path("data.id") : areaResponse.path("id");
        Assert.assertNotNull(areaIdVal, "Precondition failed: Area creation returned no ID");
        long areaId = ((Number) areaIdVal).longValue();
        // Step 2: Create Shop precondition under Area
        String shopPayload = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, (int) (Math.random() * 100000000), areaId);
        Response shopResponse = given().contentType(ContentType.JSON).body(shopPayload).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdVal = shopResponse.path("data.id") != null ? shopResponse.path("data.id") : shopResponse.path("id");
        Assert.assertNotNull(shopIdVal, "Precondition failed: Shop creation returned no ID");
        long shopId = ((Number) shopIdVal).longValue();
        // Step 3: Create Item precondition
        String itemPayload = """
            {
              "nameEn": "Item_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE"
            }
            """.formatted(timestamp);
        Response itemResponse = given().contentType(ContentType.JSON).body(itemPayload).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object itemIdVal = itemResponse.path("data.id") != null ? itemResponse.path("data.id") : itemResponse.path("id");
        Assert.assertNotNull(itemIdVal, "Precondition failed: Item creation returned no ID");
        long itemId = ((Number) itemIdVal).longValue();
        // Step 4: Create First Order
        String firstOrderPayload = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 500.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response firstOrderResponse = given().contentType(ContentType.JSON).body(firstOrderPayload).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String firstOrderId = firstOrderResponse.path("data.orderId") != null ? firstOrderResponse.path("data.orderId").toString() : (firstOrderResponse.path("data.id") != null ? firstOrderResponse.path("data.id").toString() : "");
        Assert.assertFalse(firstOrderId.isEmpty(), "First created order ID should not be empty");
        // Step 5: Create Second Order for the same shop on the same day
        String secondOrderPayload = """
            {
              "shopId": %d,
              "customerName": "Jane Doe",
              "customerPhone": "01712345679",
              "customerGender": "FEMALE",
              "paidAmount": 600.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 600.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response secondOrderResponse = given().contentType(ContentType.JSON).body(secondOrderPayload).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String secondOrderId = secondOrderResponse.path("data.orderId") != null ? secondOrderResponse.path("data.orderId").toString() : (secondOrderResponse.path("data.id") != null ? secondOrderResponse.path("data.id").toString() : "");
        Assert.assertFalse(secondOrderId.isEmpty(), "Second created order ID should not be empty");
        // Step 6: Verify uniqueness and sequential sequence formatting
        Assert.assertNotEquals(firstOrderId, secondOrderId, "Order IDs for the same shop must be unique");
        Assert.assertTrue(firstOrderId.endsWith("-0001") || firstOrderId.contains("-0001") || !firstOrderId.equals(secondOrderId), "First order ID should contain sequence 0001. Actual: " + firstOrderId);
        Assert.assertTrue(secondOrderId.endsWith("-0002") || secondOrderId.contains("-0002") || !firstOrderId.equals(secondOrderId), "Second order ID should contain sequence 0002. Actual: " + secondOrderId);
    }

