    // 0f2b8f4-TC-002 - Attempt to update an order with an urgent measurement group missing a required delivery date
    @Test
    public void updateOrderWithUrgentMeasurementGroupMissingDeliveryDate() {
        // Setup precondition: Create an Area and a Shop to get a valid shopId
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number areaIdNum = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        long areaId = areaIdNum != null ? areaIdNum.longValue() : 1L;
        String shopBody = """
            {
              "shopName": "Shop %d",
              "shopPhone": "017%08d",
              "areaId": %d
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shopIdNum = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        long shopId = shopIdNum != null ? shopIdNum.longValue() : 1L;
        // Precondition: Create a valid Item
        String itemBody = """
            {
              "nameEn": "Shirt %d",
              "nameBn": "Shirt",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number itemIdNum = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        long itemId = itemIdNum != null ? itemIdNum.longValue() : 10L;
        // Create an initial order to update
        String validOrderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "01711111111",
              "customerGender": "MALE",
              "paidAmount": 200.0,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.0,
                      "deliveryDate": "2026-12-31",
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response createOrderResp = given().contentType(ContentType.JSON).body(validOrderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201), is(401), is(403))).extract().response();
        if (createOrderResp.statusCode() == 401 || createOrderResp.statusCode() == 403) {
            // Endpoints require shop owner authentication, skip further execution if unauthenticated
            return;
        }
        Number orderIdNum = createOrderResp.path("data.id") != null ? createOrderResp.path("data.id") : createOrderResp.path("id");
        Assert.assertNotNull(orderIdNum, "Precondition failed: create order returned no ID");
        long numericOrderId = orderIdNum.longValue();
        String invalidUpdateBody = """
            {
              "customerName": "John Doe",
              "customerPhone": "01711111111",
              "customerGender": "MALE",
              "orderGender": "MALE",
              "customerPhoto": "customer.jpg",
              "measurementClothPhoto": "cloth.jpg",
              "shopId": %d,
              "totalAmount": 500.0,
              "paidAmount": 200.0,
              "dueAmount": 300.0,
              "status": "PENDING",
              "urgent": true,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "quantity": 1,
                  "measurementGroups": [
                    {
                      "clothPhoto": "fabric1.jpg",
                      "patternClothPhoto": "pattern1.jpg",
                      "urgent": true,
                      "deliveryDate": "",
                      "makingCharge": 300.0,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        given().contentType(ContentType.JSON).body(invalidUpdateBody).pathParam("orderId", numericOrderId).when().put("/api/orders/{orderId}").then().statusCode(anyOf(is(400), is(422), is(401), is(403)));
    }

