    // 92528b6-TC-001 - Verify that order IDs are generated correctly for different shops on the same day
    @Test
    public void testOrderSequenceGenerationForDifferentShops() {
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number areaIdNum = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdNum, "Precondition failed: Area creation returned no ID");
        long areaId = areaIdNum.longValue();
        // Create Shop 1
        String shop1Body = """
            {
              "shopName": "Shop1_%d",
              "shopPhone": "019%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, areaId);
        Response shop1Resp = given().contentType(ContentType.JSON).body(shop1Body).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shop1IdNum = shop1Resp.path("id") != null ? shop1Resp.path("id") : shop1Resp.path("data.id");
        Assert.assertNotNull(shop1IdNum, "Precondition failed: Shop 1 creation returned no ID");
        long shop1Id = shop1IdNum.longValue();
        // Create Shop 2
        String shop2Body = """
            {
              "shopName": "Shop2_%d",
              "shopPhone": "016%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, (timestamp + 1) % 100000000L, areaId);
        Response shop2Resp = given().contentType(ContentType.JSON).body(shop2Body).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shop2IdNum = shop2Resp.path("id") != null ? shop2Resp.path("id") : shop2Resp.path("data.id");
        Assert.assertNotNull(shop2IdNum, "Precondition failed: Shop 2 creation returned no ID");
        long shop2Id = shop2IdNum.longValue();
        // Create Item
        String itemBody = """
            {
              "nameEn": "Salwar Kameez_%d",
              "nameBn": "Salwar Kameez",
              "status": "ACTIVE"
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number itemIdNum = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemIdNum, "Precondition failed: Item creation returned no ID");
        long itemId = itemIdNum.longValue();
        // Create order for Shop 1
        String order1Body = """
            {
              "shopId": %d,
              "customerName": "Jane Smith",
              "customerPhone": "01812345678",
              "customerGender": "FEMALE",
              "paidAmount": 0.00,
              "deliveryDate": "2030-01-01",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 400.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shop1Id, itemId);
        Response order1Resp = given().contentType(ContentType.JSON).body(order1Body).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String order1Code = order1Resp.path("data.orderId") != null ? order1Resp.path("data.orderId") : order1Resp.path("orderId");
        if (order1Code != null) {
            Assert.assertTrue(order1Code.startsWith(shop1Id + "-"), "Order 1 ID should start with shop1Id prefix. Actual: " + order1Code);
            Assert.assertTrue(order1Code.endsWith("-0001"), "Order 1 ID should end with sequence -0001. Actual: " + order1Code);
        }
        // Create order for Shop 2
        String order2Body = """
            {
              "shopId": %d,
              "customerName": "Jane Smith",
              "customerPhone": "01812345678",
              "customerGender": "FEMALE",
              "paidAmount": 0.00,
              "deliveryDate": "2030-01-01",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 400.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shop2Id, itemId);
        Response order2Resp = given().contentType(ContentType.JSON).body(order2Body).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String order2Code = order2Resp.path("data.orderId") != null ? order2Resp.path("data.orderId") : order2Resp.path("orderId");
        if (order2Code != null) {
            Assert.assertTrue(order2Code.startsWith(shop2Id + "-"), "Order 2 ID should start with shop2Id prefix. Actual: " + order2Code);
            Assert.assertTrue(order2Code.endsWith("-0001"), "Order 2 ID should end with sequence -0001. Actual: " + order2Code);
        }
    }

