    // 92528b6-TC-023 - Update an existing order and verify the order ID remains unchanged
    @Test
    public void updateExistingOrderKeepsOrderIdUnchanged() {
        createdAreaId = createArea("update");
        createdShopId = createShop5(createdAreaId);
        createdItemId = createItem5();
        String createBody = buildOrderBody(createdShopId, createdItemId, "Original Name");
        Response createResp = given().contentType(ContentType.JSON).body(createBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Object orderIdObj = createResp.path("data.orderId");
        if (orderIdObj == null)
            orderIdObj = createResp.path("data.id");
        Assert.assertNotNull(orderIdObj, "Precondition failed: order create returned no orderId; body=" + createResp.asString());
        String originalOrderId = orderIdObj.toString();
        firstOrderBusinessId = originalOrderId;
        String updateBody = """
            {
              "shopId": %d,
              "customerName": "John Doe Updated",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2099-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 100,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(createdShopId, System.currentTimeMillis() % 100000000L, createdItemId);
        Response updateResp = given().contentType(ContentType.JSON).body(updateBody).when().put("/api/orders/{orderId}", originalOrderId).then().statusCode(anyOf(is(200), is(204))).extract().response();
        Response getResp = given().contentType(ContentType.JSON).when().get("/api/orders/{orderId}", originalOrderId).then().statusCode(200).extract().response();
        Object fetchedId = getResp.path("data.orderId");
        if (fetchedId == null)
            fetchedId = getResp.path("data.id");
        Assert.assertEquals(fetchedId, originalOrderId, "Order ID should remain unchanged after update");
    }

    // 92528b6-TC-024 - Verify concurrent order creation generates unique sequential order IDs
    @Test
    public void concurrentOrderCreationGeneratesUniqueSequentialOrderIds() {
        createdAreaId = createArea("concurrent");
        createdShopId = createShop5(createdAreaId);
        createdItemId = createItem5();
        long ts = System.currentTimeMillis();
        String body1 = """
            {
              "shopId": %d,
              "customerName": "Test User",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2099-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 100,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(createdShopId, ts % 100000000L, createdItemId);
        String body2 = """
            {
              "shopId": %d,
              "customerName": "Test User",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2099-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 100,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(createdShopId, (ts + 1) % 100000000L, createdItemId);
        Response r1 = given().contentType(ContentType.JSON).body(body1).when().post("/api/orders").then().statusCode(200).extract().response();
        Response r2 = given().contentType(ContentType.JSON).body(body2).when().post("/api/orders").then().statusCode(200).extract().response();
        Object id1Obj = r1.path("data.orderId");
        if (id1Obj == null)
            id1Obj = r1.path("data.id");
        Object id2Obj = r2.path("data.orderId");
        if (id2Obj == null)
            id2Obj = r2.path("data.id");
        Assert.assertNotNull(id1Obj, "First order should have an id; body=" + r1.asString());
        Assert.assertNotNull(id2Obj, "Second order should have an id; body=" + r2.asString());
        Assert.assertNotEquals(id1Obj.toString(), id2Obj.toString(), "Concurrent orders must have unique order IDs");
    }

    // 92528b6-TC-026 - Verify that order creation with a maliciously crafted shop ID is rejected safely
    @Test
    public void orderCreationWithMaliciousShopIdIsRejectedSafely() {
        createdAreaId = createArea("malicious");
        createdShopId = createShop5(createdAreaId);
        createdItemId = createItem5();
        String[] maliciousShopIds = new String[] { "1 OR 1=1", "-1", "99999999999999999999" };
        for (String malicious : maliciousShopIds) {
            String body = """
                {
                  "shopId": "%s",
                  "customerName": "Mallory",
                  "customerPhone": "017%08d",
                  "customerGender": "MALE",
                  "paidAmount": 0,
                  "deliveryDate": "2099-12-31",
                  "items": [
                    {
                      "itemId": %d,
                      "measurementGroups": [
                        {
                          "makingCharge": 100,
                          "measurements": []
                        }
                      ]
                    }
                  ]
                }
                """.formatted(malicious, System.currentTimeMillis() % 100000000L, createdItemId);
            Response resp = given().contentType(ContentType.JSON).body(body).when().post("/api/orders").then().extract().response();
            int status = resp.statusCode();
            Assert.assertTrue(status == 400 || status == 404 || status == 422 || status >= 500 == false && status >= 400, "Expected a 4xx rejection for malicious shopId '" + malicious + "', got " + status);
            Assert.assertTrue(status >= 400 && status < 500, "Expected 4xx for malicious shopId '" + malicious + "', got " + status + ". Response body: " + resp.asString());
        }
    }

