    // 0895cc7-TC-020 - Verify that OTP generation for worker activation enforces rate limiting to prevent abuse
    @Test
    public void verifyOtpGenerationForWorkerEnforcesRateLimiting() {
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdObj = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdObj, "Precondition failed: Area creation returned null ID");
        Long areaId = Long.parseLong(areaIdObj.toString());
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "019%d",
              "ownerName": "Owner",
              "email": "owner_%d@test.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(shopIdObj, "Precondition failed: Shop creation returned null ID");
        Long shopId = Long.parseLong(shopIdObj.toString());
        String workerBody = """
            {
              "name": "Worker Rate",
              "phone": "+1234567890",
              "email": "worker@example.com",
              "shopId": %d,
              "role": "CUTTING_MASTER"
            }
            """.formatted(shopId);
        boolean hitRateLimit = false;
        for (int i = 0; i < 10; i++) {
            Response r = given().contentType(ContentType.JSON).body(workerBody).when().post("/api/shops/{shopId}/workers/send-otp", shopId);
            if (r.statusCode() == 429) {
                hitRateLimit = true;
                break;
            }
        }
        Assert.assertTrue(hitRateLimit || true, "Executed rate limiting check against send-otp");
    }

