    // 0895cc7-TC-027
    @Test
    public void testAddWorkerWithMaliciousInputIsRejectedOrSanitized() {
        long timestamp = System.currentTimeMillis();
        // Precondition: Create Area
        String areaPayload = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number areaIdNum = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdNum, "Precondition failed: Area creation returned no ID");
        long areaId = areaIdNum.longValue();
        // Precondition: Create Shop
        String shopPayload = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "latitude": 23.8103,
              "longitude": 90.4125,
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopPayload).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Number shopIdNum = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(shopIdNum, "Precondition failed: Shop creation returned no ID");
        long shopId = shopIdNum.longValue();
        String maliciousPayload = """
            {
              "name": "Test Worker<script>alert('xss')</script>",
              "phone": "+8801700000000",
              "email": "testworker%d@example.com",
              "address": "123 Main St; DROP TABLE workers;--",
              "shopId": %d,
              "status": true,
              "role": "CUTTING_MASTER"
            }
            """.formatted(timestamp, shopId);
        Response response = given().contentType(ContentType.JSON).body(maliciousPayload).when().post("/api/shops/{shopId}/workers", shopId);
        int statusCode = response.getStatusCode();
        Assert.assertTrue(statusCode == 400 || statusCode == 422 || statusCode == 200 || statusCode == 201, "Unexpected status code: " + statusCode);
        if (statusCode == 200 || statusCode == 201) {
            String name = response.path("data.name") != null ? response.path("data.name") : response.path("name");
            String address = response.path("data.address") != null ? response.path("data.address") : response.path("address");
            Assert.assertNotNull(name, "Created worker should return name");
            Assert.assertNotNull(address, "Created worker should return address");
        }
    }

