    // 4502dc7-TC-007 - Verify that OTP generation for worker activation is rejected if the requesting user has no pending shop change request
    @Test
    public void testSendOtpNoPendingRequest() {
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation failed");
        String shopBody = """
            {
              "shopName": "Test Shop %d",
              "shopPhone": "017%d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/%d/shops".formatted(areaId)).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation failed");
        String workerBody = """
            {
              "name": "Test Worker",
              "email": "testworker@example.com",
              "phoneNumber": "+8801700000000",
              "role": "CUTTING_MASTER"
            }
            """;
        given().contentType(ContentType.JSON).body(workerBody).when().post("/api/shops/%d/workers/send-otp".formatted(shopId)).then().statusCode(anyOf(is(400), is(401), is(403)));
    }

