    // ad47f14-TC-002
    @Test
    public void attemptToSubmitMeasurementWithTextParameterContainingNonTextData() {
        long timestamp = System.currentTimeMillis();
        // Precondition 1: Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned null ID");
        // Precondition 2: Create Shop under Area
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "01700000000",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned null ID");
        // Precondition 3: Create Item
        String itemBody = """
            {
              "nameEn": "Item_%d",
              "nameBn": "Item",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp);
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned null ID");
        // Action under test: Submit order with numeric non-text value in TEXT parameter field ('specialInstruction')
        String invalidOrderBody = """
            {
              "shopId": %d,
              "customerName": "Customer_%d",
              "customerPhone": "01800000000",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": 50,
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp, itemId);
        given().contentType(ContentType.JSON).body(invalidOrderBody).when().post("/api/orders").then().statusCode(anyOf(is(400), is(422)));
    }

