    @Test
    public void attemptToMakeAPaymentWithANegativePaymentAmount() {
        // Step 1: Create Area
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer areaId = areaResp.path("data.id");
        if (areaId == null) {
            areaId = areaResp.path("id");
        }
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // Step 2: Create Shop under Area
        String shopBody = """
            {
              "shopName": "Test Shop %d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer shopId = shopResp.path("data.id");
        if (shopId == null) {
            shopId = shopResp.path("id");
        }
        Assert.assertNotNull(shopId, "Precondition failed: Shop ID is null");
        // Step 3: Create Item
        String itemBody = """
            {
              "nameEn": "Shirt %d",
              "nameBn": "Shirt",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer itemId = itemResp.path("data.id");
        if (itemId == null) {
            itemId = itemResp.path("id");
        }
        Assert.assertNotNull(itemId, "Precondition failed: Item ID is null");
        // Step 4: Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2030-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 5000,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, System.currentTimeMillis() % 100000000L, itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object extractedId = orderResp.path("data.id");
        if (extractedId == null) {
            extractedId = orderResp.path("id");
        }
        Assert.assertNotNull(extractedId, "Precondition failed: Order ID is null");
        String orderId = String.valueOf(extractedId);
        // Step 5: Execute Test Case - Post payment with negative amount
        String paymentBody = """
            {
              "paymentAmount": -100
            }
            """;
        given().contentType(ContentType.JSON).body(paymentBody).when().post("/api/orders/{orderId}/pay", orderId).then().statusCode(anyOf(is(400), is(422)));
    }

