    // Helper method to create prerequisites (Area -> Shop -> Item -> Order)
    private Long createOrderAndGetId() {
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // 2. Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), (int) (Math.random() * 100000000), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("data.id") != null ? ((Number) shopResp.path("data.id")).longValue() : ((Number) shopResp.path("id")).longValue();
        Assert.assertNotNull(shopId, "Precondition failed: Shop ID is null");
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "Shirt",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        Assert.assertNotNull(itemId, "Precondition failed: Item ID is null");
        // 4. Create Order with totalAmount 500.00 and paidAmount 200.00 (makingCharge = 500.00, paidAmount = 200.00)
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer %d",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 200.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, System.currentTimeMillis(), (int) (Math.random() * 100000000), itemId);
        Response orderResp = given().contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long orderId = orderResp.path("data.id") != null ? ((Number) orderResp.path("data.id")).longValue() : ((Number) orderResp.path("id")).longValue();
        Assert.assertNotNull(orderId, "Precondition failed: Order ID is null");
        return orderId;
    }

