    // d7a62e8-TC-001
    @Test
    public void shopOwnerCreatesOrderForUnownedShop() {
        // Setup: Create an Area and Item to satisfy foreign key constraints
        String areaPayload = """
            {
              "name": "Security Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer areaId = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no ID");
        String itemPayload = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().contentType(ContentType.JSON).body(itemPayload).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer itemId = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no ID");
        // Send order request for unowned shop ID (999999)
        String orderPayload = """
            {
              "shopId": 999999,
              "customerName": "John Doe",
              "customerPhone": "01711111111",
              "customerGender": "MALE",
              "paidAmount": 0,
              "trialDate": "2026-01-20",
              "deliveryDate": "2026-01-25",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 50,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(itemId);
        given().contentType(ContentType.JSON).body(orderPayload).when().post("/api/orders").then().statusCode(anyOf(is(401), is(403), is(400), is(404)));
    }

