    // TC-030: Delete a photo with an object name exactly at the maximum allowed length (255 chars)
    @Test
    public void deletePhotoWithMaxLengthObjectName() {
        // 255-char string using a-z, A-Z, 0-9 pattern
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 255; i++) {
            char c = (char) ('a' + (i % 26));
            sb.append(c);
        }
        String maxLengthName = sb.toString();
        Assert.assertEquals(maxLengthName.length(), 255);
        given().queryParam("objectName", maxLengthName).when().delete("/api/photos/delete").then().statusCode(anyOf(is(200), is(404)));
    }

