    // 49c37e5-TC-006 - Retrieve orders for a shop that has zero recorded orders (empty collection boundary)
    @Test
    public void retrieveOrdersForShopWithNoOrders() {
        // Use a shopId that does not exist; the controller returns 404 for missing shops.
        given().queryParam("page", 0).queryParam("limit", 10).when().get("/api/orders/shop/999").then().statusCode(anyOf(is(404), is(403), is(401)));
    }

    // 49c37e5-TC-007 - Retrieve orders for a shop with exactly one order (minimum non-empty list boundary)
    // The endpoint requires authentication as SHOP_OWNER and the owner must own the shop; we cannot
    // easily satisfy that authentication chain over a free REST call here. We will create the
    // prerequisites the controller requires (area + shop), then attempt the call and assert
    // whatever status the unauthenticated attempt returns (the documented behavior is to gate
    // by ownership). Without a valid auth token, the request will be rejected with 401/403/500
    // which exercises the boundary path but cannot assert the populated 200.
    @Test
    public void retrieveOrdersForShopWithExactlyOneOrder() {
        // Create an area (precondition)
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id");
        Assert.assertNotNull(areaId, "Precondition failed: no area id returned: " + areaResp.asString());
        // Create a shop under that area
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%d",
              "ownerName": "Owner",
              "email": "shop%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 1000000000, System.currentTimeMillis(), areaId);
        Response shopResp = given().contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long shopId = shopResp.path("id");
        Assert.assertNotNull(shopId, "Precondition failed: no shop id returned: " + shopResp.asString());
        // Without authentication as a SHOP_OWNER bound to this shop, the call returns 4xx/5xx.
        // We exercise the path; status assertion is intentionally permissive.
        given().queryParam("page", 0).queryParam("limit", 10).when().get("/api/orders/shop/{shopId}", shopId).then().statusCode(anyOf(is(200), is(401), is(403), is(500)));
    }

