    // ded9b39-TC-030 - Verify that item creation and update enforce rate limiting to prevent abuse
    @Test
    public void testItemCreationRateLimitingOrSuccess() {
        String itemPayload = """
            {
              "nameEn": "Rate Limit Test Item",
              "nameBn": "টেস্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "চেস্ট",
                  "unit": "cm",
                  "type": "NUMERIC",
                  "nsId": "CHST"
                }
              ]
            }
            """;
        int lastStatusCode = 200;
        for (int i = 0; i < 20; i++) {
            Response res = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemPayload).when().post("/api/items");
            lastStatusCode = res.getStatusCode();
            if (lastStatusCode == 429) {
                break;
            }
        }
        Assert.assertTrue(lastStatusCode == 200 || lastStatusCode == 429, "Expected 200 OK or 429 Too Many Requests, but got: " + lastStatusCode);
    }

