    // 226f7f9-TC-032 - Verify that OTP verification rejects replayed OTPs after successful use
    @Test
    public void verifyOtpReplayRejection2() {
        String email = "user_%d@example.com".formatted(System.currentTimeMillis());
        String phone = "+88017%08d".formatted(System.currentTimeMillis() % 100000000L);
        // Request OTP to generate it
        Response requestOtpResp = given().queryParam("email", email).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = requestOtpResp.path("data");
        Assert.assertNotNull(otp, "Precondition failed: OTP not returned");
        String verifyPayload = """
            {
              "phoneNumber": "%s",
              "otp": "%s"
            }
            """.formatted(phone, otp);
        // 1. First verification request should succeed
        given().contentType(ContentType.JSON).body(verifyPayload).when().post("/api/auth/verify-otp").then().statusCode(200);
        // 2. Replayed verification request should be rejected
        given().contentType(ContentType.JSON).body(verifyPayload).when().post("/api/auth/verify-otp").then().statusCode(anyOf(is(400), is(401), is(403)));
    }

    // 226f7f9-TC-033 - Verify that OTP verification rejects expired OTPs
