    // 9e06ad6-TC-018 - Verify that raw storage paths for measurement cloth photos are not leaked in error messages or logs during order retrieval
    @Test
    public void verifyRawStoragePathsNotLeakedInErrorMessages() {
        // Authenticate as admin to setup shop and owner
        String adminLoginBody = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response adminLoginResp = given().contentType(ContentType.JSON).body(adminLoginBody).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String adminToken = adminLoginResp.getHeader("Authorization");
        // Create Area
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Long areaId = areaResp.jsonPath().getLong("data.id");
        // Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), System.currentTimeMillis(), areaId);
        Response shopResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Long shopId = shopResp.jsonPath().getLong("id");
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation failed");
        // Attempt to get non-existent order code or path-traversal code under admin token
        String responseBody = given().header("Authorization", adminToken).when().get("/api/orders/../../invalid-path").then().statusCode(anyOf(is(400), is(404), is(500))).extract().asString();
        Assert.assertFalse(responseBody.contains("minio"), "Response leaked storage provider details: " + responseBody);
        Assert.assertFalse(responseBody.contains("/var/data"), "Response leaked local path details: " + responseBody);
    }

