    // Helper method to setup shop owner and obtain token
    private String[] setupShopAndOwnerToken() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area (Admin)
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Integer areaId = areaResp.path("data.id");
        if (areaId == null) {
            areaId = areaResp.path("id");
        }
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // 2. Create Shop (Admin)
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "123 Test St",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, (int) (timestamp % 100000000L), timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Integer shopId = shopResp.path("data.id");
        if (shopId == null) {
            shopId = shopResp.path("id");
        }
        Assert.assertNotNull(shopId, "Precondition failed: Shop ID is null");
        // 3. Request OTP, verify OTP, set PIN and Login for Owner
        String ownerEmail = "owner_%d@example.com".formatted(timestamp);
        String ownerPhone = "017%08d".formatted((int) (timestamp % 100000000L));
        Response otpResp = given().queryParam("email", ownerEmail).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        Assert.assertNotNull(otp, "Precondition failed: OTP is null");
        String verifyOtpBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s"
            }
            """.formatted(ownerPhone, otp);
        given().contentType(ContentType.JSON).body(verifyOtpBody).when().post("/api/auth/verify-otp").then().statusCode(200);
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "ConfirmPin": "1234"
            }
            """.formatted(ownerPhone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(ownerPhone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String ownerToken = loginResp.getHeader("Authorization");
        if (ownerToken != null && ownerToken.startsWith("Bearer ")) {
            ownerToken = ownerToken.substring(7);
        }
        Assert.assertNotNull(ownerToken, "Precondition failed: Owner token is null");
        return new String[] { ownerToken, String.valueOf(shopId) };
    }

