    // ad5f663-TC-021
    @Test
    public void testLastMeasurementRejectsInjectionAttempts() {
        // Setup: Create Area, Shop, Owner, Item to query last measurement cleanly
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Object areaIdObj = areaResp.path("data.id");
        Long areaId = areaIdObj != null ? Long.valueOf(areaIdObj.toString()) : 1L;
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "123 Test St",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Object shopIdObj = shopResp.path("id");
        Long shopId = shopIdObj != null ? Long.valueOf(shopIdObj.toString()) : 1L;
        // Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(timestamp);
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Object itemIdObj = itemResp.path("data.id");
        Long itemId = itemIdObj != null ? Long.valueOf(itemIdObj.toString()) : 1L;
        // Test Step: Send injection payload in phone parameter
        String injectionPhone = "+1234567890' OR '1'='1";
        given().header("Authorization", "Bearer " + adminToken).queryParam("phone", injectionPhone).queryParam("customerId", 99999).queryParam("itemId", itemId).when().get("/api/orders/last-measurement").then().statusCode(anyOf(is(400), is(404), is(403)));
    }

