        String nonExistentPhone = "+9999999999";
        Response response = given().header("Authorization", "Bearer " + shopOwnerToken).queryParam("phone", nonExistentPhone).when().get("/api/customers/by-phone").then().statusCode(200).body("status", equalTo("success")).body("message", equalTo("No customers found for this phone number")).body("data", empty()).extract().response();
