    // a9395cb-TC-024 - Verify that retrieving an item by ID enforces proper authorization (insecure direct object reference)
    @Test
    public void verifyItemByIdAuthorization() {
        // Precondition: Create an item
        String itemName = "Shirt_" + System.currentTimeMillis();
        String itemReq = """
            {
              "nameEn": "%s",
              "nameBn": "shirt",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(itemName);
        Response createResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemReq).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object idObj = createResp.path("data.id");
        if (idObj == null) {
            idObj = createResp.path("id");
        }
        Assert.assertNotNull(idObj, "Precondition failed: Item id was null");
        Long itemId = Long.valueOf(idObj.toString());
        // Step 1: Unauthenticated request should return 401 or 403
        given().when().get("/api/items/{id}", itemId).then().statusCode(anyOf(is(401), is(403)));
        // Step 2: Authenticated request should return 200 OK
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/items/{id}", itemId).then().statusCode(200).body("data.id", equalTo(itemId.intValue()));
    }

