    private AuthInfo createShopAndOwner() {
        long timestamp = System.currentTimeMillis();
        String areaName = "Area_" + timestamp;
        String areaBody = """
            {
              "name": "%s"
            }
            """.formatted(areaName);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer areaIdInt = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Long areaId = areaIdInt.longValue();
        String shopPhone = "017" + String.format("%08d", (int) (timestamp % 100000000L));
        String shopEmail = "shop_" + timestamp + "@example.com";
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "%s",
              "latitude": 23.8103,
              "longitude": 90.4125,
              "ownerName": "Owner_%d",
              "email": "%s",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, shopPhone, timestamp, shopEmail, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer shopIdInt = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Long shopId = shopIdInt.longValue();
        // Request OTP for shop owner
        given().contentType(ContentType.JSON).when().post("/api/auth/request-otp?email=" + shopEmail).then().statusCode(200);
        // In test mode, OTP is fixed or returned in data
        String otp = "123456";
        String verifyOtpBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s"
            }
            """.formatted(shopPhone, otp);
        given().contentType(ContentType.JSON).body(verifyOtpBody).when().post("/api/auth/verify-otp").then();
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(shopPhone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then();
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(shopPhone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String ownerToken = loginResp.getHeader("Authorization");
        if (ownerToken != null && ownerToken.startsWith("Bearer ")) {
            ownerToken = ownerToken.substring(7);
        } else {
            ownerToken = loginResp.path("data.token");
        }
        return new AuthInfo(ownerToken, shopId);
    }

