    // 9f19f61-TC-025 - Verify that paginated order retrieval by phone number enforces proper authorization (insecure direct object reference) - unauthorized user cannot access another user's orders
    @Test
    public void verifyPaginatedOrderRetrievalByPhoneAuthorization() {
        // Setup order for User A's shop
        SetupFixture fixtureA = createSetupFixture("ItemA");
        String targetPhone = "+8801712345678";
        createOrder(fixtureA.shopId, fixtureA.itemId, targetPhone);
        // Setup User B (Shop B Owner) who does not own orders with targetPhone
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "AreaB_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Number areaIdNum = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        String shopBBody = """
            {
              "shopName": "ShopB_%d",
              "shopPhone": "018%08d",
              "ownerName": "OwnerB_%d",
              "email": "ownerB_%d@example.com",
              "address": "Address B",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, Math.abs(timestamp % 100000000L), timestamp, timestamp, areaIdNum.longValue());
        Response shopBResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBBody).when().post("/api/areas/" + areaIdNum + "/shops").then().statusCode(200).extract().response();
        Number shopBIdNum = shopBResp.path("data.id") != null ? shopBResp.path("data.id") : shopBResp.path("id");
        // Request OTP for User B
        String userBEmail = "ownerB_" + timestamp + "@example.com";
        Response otpResp = given().queryParam("email", userBEmail).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        Assert.assertNotNull(otp, "Precondition failed: OTP not returned");
        String phoneB = "018" + String.format("%08d", Math.abs(timestamp % 100000000L));
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(phoneB, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        // Login as User B
        String loginBody = """
            {
              "username": "ownerB_%d@example.com",
              "pin": "1234"
            }
            """.formatted(timestamp);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String userBToken = loginResp.getHeader("Authorization");
        if (userBToken != null && userBToken.startsWith("Bearer ")) {
            userBToken = userBToken.substring(7);
        } else {
            userBToken = loginResp.path("data.accessToken");
        }
        // Perform request as User B trying to access orders of targetPhone (belonging to Shop A)
        given().header("Authorization", "Bearer " + userBToken).queryParam("phone", targetPhone).queryParam("page", 0).queryParam("limit", 10).when().get("/api/orders/by-phone").then().statusCode(anyOf(is(200), is(403), is(404)));
    }

