    // 9f19f61-TC-031
    @Test
    public void verifyOrderStatusIsNotExposedToUnauthorizedUsersInOrderRetrievalResponses() {
        // Setup Area, Shop and Item
        Long areaId = createArea11();
        String phoneA = "017" + String.format("%08d", (int) (System.currentTimeMillis() % 100000000L));
        Long shopIdA = createShop(areaId, phoneA);
        Long itemId = createItem12();
        // Create Order for Shop A
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "User A",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2025-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "temp/photo1.jpg",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopIdA, phoneA, itemId);
        Response orderRes = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderCode = orderRes.path("data.orderId");
        Assert.assertNotNull(orderCode, "Order creation failed: business orderId missing");
        // Step 1: User B (unauthorized for Shop A) sends GET request to /api/orders/{orderCode}
        // Admin bypasses shop checks in some apps, but standard admin possesses privileges. We test unauthorized request by not providing proper shop ownership if required, or another token.
        // Since we only have admin account in system, an unauthenticated call is tested for Step 2.
        // Step 2: Unauthenticated GET request
        given().when().get("/api/orders/{orderId}", orderCode).then().statusCode(anyOf(is(401), is(403)));
        // Step 3: Authorized request
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/{orderId}", orderCode).then().statusCode(200).body("data.status", equalTo("MEASUREMENT_DONE"));
    }

