        String responseBody = given().header("Authorization", authToken).contentType(ContentType.JSON).body(invalidOrderPayload).when().post("/api/orders").then().statusCode(anyOf(is(500), is(400))).extract().asString();
        Assert.assertTrue(responseBody.toLowerCase().contains("unexpected error"), "Expected response body to contain detailed error message. Body was: " + responseBody);
