    // TC-003 - Verify retrieving an order by string ID displays all measurement data correctly
    @Test
    public void testGetOrderByStringIdDisplaysMeasurementDataCorrectly() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area (Admin)
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdObj = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdObj, "Precondition failed: Area ID is null");
        Long areaId = Long.valueOf(areaIdObj.toString());
        // 2. Create Shop under Area (Admin)
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "123 Test St",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(shopIdObj, "Precondition failed: Shop ID is null");
        Long shopId = Long.valueOf(shopIdObj.toString());
        // 3. Create Item with Measuring Parameters (Admin/Authenticated)
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "ছাতি",
                  "unit": "inch",
                  "type": "NUMERIC",
                  "suggestiveValues": ["38", "40"],
                  "nsId": "P%03d"
                }
              ]
            }
            """.formatted(timestamp, timestamp, (timestamp % 1000));
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object itemIdObj = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemIdObj, "Precondition failed: Item ID is null");
        Long itemId = Long.valueOf(itemIdObj.toString());
        // Note: Order creation requires SHOP_OWNER role owning shopId. Since admin bypasses row-level ownership (@shopSecurity),
        // we use adminToken to create and retrieve the order.
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "customerPhoto": "http://example.com/cust.jpg",
              "paidAmount": 100.00,
              "trialDate": "2025-06-01",
              "deliveryDate": "2025-06-10",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Handle with care",
                      "clothPhoto": "http://example.com/cloth.jpg",
                      "patternClothPhoto": "http://example.com/pattern.jpg",
                      "measurementClothPhoto": "http://example.com/mcloth.jpg",
                      "designDrawingPhoto": "http://example.com/design.jpg",
                      "deliveryDate": "2025-06-10",
                      "makingCharge": 500.00,
                      "measurements": [
                        {
                          "nameEn": "Chest",
                          "nameBn": "ছাতি",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": 40.0,
                          "nsId": "P%03d"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp % 100000000L, itemId, (timestamp % 1000));
        Response createOrderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        String businessOrderId = createOrderResp.path("data.orderId");
        if (businessOrderId == null) {
            businessOrderId = createOrderResp.path("data.orderCode");
        }
        Assert.assertNotNull(businessOrderId, "Precondition failed: Business Order String ID was not returned in response");
        // Step 2 & 3: Retrieve order by string ID and verify expected details
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/{orderId}", businessOrderId).then().statusCode(200).body("status", equalTo("success")).body("data.orderId", equalTo(businessOrderId)).body("data.orderItems", not(empty())).body("data.orderItems[0].measurementGroups[0].measurements[0].nameEn", equalTo("Chest")).body("data.orderItems[0].measurementGroups[0].measurements[0].nameBn", equalTo("ছাতি")).body("data.orderItems[0].measurementGroups[0].clothPhoto", notNullValue()).body("data.orderItems[0].measurementGroups[0].patternClothPhoto", notNullValue());
    }

