    // Helper method to create area, shop, item, order item status setup
    // returns orderItemId
    private Long createOrderItemForStatusUpdate(String ownerToken, Long shopId) {
        // Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Long itemId = itemResp.path("data.id") != null ? ((Number) itemResp.path("data.id")).longValue() : ((Number) itemResp.path("id")).longValue();
        // Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2030-01-01",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "temp/cloth.jpg",
                      "deliveryDate": "2030-01-01",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response orderResp = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        // Since OrderSummaryResponse does not list orderItemId directly in standard path, extract order item status endpoint ID if returned or from getOrder
        // The endpoint is PUT /api/orders/items/{orderItemId}/status
        // Let's get numeric id of order
        Long orderDbId = ((Number) orderResp.path("data.id")).longValue();
        String orderCode = orderResp.path("data.orderId");
        Response detailedOrderResp = given().header("Authorization", "Bearer " + ownerToken).when().get("/api/orders/{orderId}", orderCode).then().statusCode(200).extract().response();
        Long orderItemId = ((Number) detailedOrderResp.path("data.orderItems[0].id")).longValue();
        return orderItemId;
    }

