    // d3da340-TC-017 - Verify that order creation response does not expose sensitive system details in error messages
    @Test
    public void orderCreationInvalidDataSecurityCheck() {
        Long areaId = createArea13();
        Long shopId = createShop10(areaId);
        Long itemId = createItem15();
        String invalidOrderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "1234567890",
              "customerGender": "MALE",
              "customerPhoto": "https://example.com/photo.jpg",
              "paidAmount": -1000,
              "deliveryDate": "2023-10-20",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": []
                }
              ]
            }
            """.formatted(shopId, itemId);
        String responseBody = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(invalidOrderBody).when().post("/api/orders").then().statusCode(400).extract().asString();
        Assert.assertFalse(responseBody.contains("Exception"), "Response should not contain Exception stack traces: " + responseBody);
        Assert.assertFalse(responseBody.contains("org.hibernate"), "Response should not contain Hibernate trace: " + responseBody);
        Assert.assertFalse(responseBody.contains("org.springframework"), "Response should not contain Spring trace: " + responseBody);
    }

