    // 113f2a9-TC-004
    @Test
    public void testUpdateOrderItemStatusToReadyForDelivery() {
        Long areaId = createArea14();
        Long shopId = createShop11(areaId);
        Long itemId = createItem16();
        Response createOrderResp = createOrderFixture3(shopId, itemId);
        Assert.assertTrue(createOrderResp.getStatusCode() == 200 || createOrderResp.getStatusCode() == 201, "Failed to create order precondition: " + createOrderResp.asString());
        String orderCode = createOrderResp.path("data.orderId");
        // Get detailed order to find the orderItemId
        Response getOrderResp = given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/" + orderCode).then().statusCode(200).extract().response();
        Number orderItemIdNum = getOrderResp.path("data.orderItems[0].measurementGroups[0].id");
        if (orderItemIdNum == null) {
            orderItemIdNum = getOrderResp.path("data.orderItems[0].id");
        }
        Assert.assertNotNull(orderItemIdNum, "Precondition failed: orderItemId not found in order details");
        Long orderItemId = orderItemIdNum.longValue();
        // Transition status step-by-step: MEASUREMENT_DONE -> CUTTING_DONE -> SEWING_DONE
        String cutStatusBody = """
            {
              "newStatus": "CUTTING_DONE"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(cutStatusBody).when().put("/api/orders/items/" + orderItemId + "/status").then().statusCode(200);
        String sewStatusBody = """
            {
              "newStatus": "SEWING_DONE"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(sewStatusBody).when().put("/api/orders/items/" + orderItemId + "/status").then().statusCode(200);
        // Step under test: SEWING_DONE -> PRESS_DONE -> READY_FOR_DELIVERY
        String pressStatusBody = """
            {
              "newStatus": "PRESS_DONE"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(pressStatusBody).when().put("/api/orders/items/" + orderItemId + "/status").then().statusCode(200);
        String readyStatusBody = """
            {
              "newStatus": "READY_FOR_DELIVERY"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(readyStatusBody).when().put("/api/orders/items/" + orderItemId + "/status").then().statusCode(200);
        // Verify detailed order response
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/" + orderCode).then().statusCode(200).body("data.orderItems[0].measurementGroups[0].orderItemStatus", equalTo("READY_FOR_DELIVERY"));
    }

