    /**
     * Helper method to setup an order and extract its first order item ID.
     * Creates area -> shop -> item -> order sequence.
     */
    private Long setupOrderAndGetItemId() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Long areaId = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        if (areaId == null) {
            Number idNum = areaResp.path("data.id");
            if (idNum != null)
                areaId = idNum.longValue();
        }
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no ID");
        // 2. Create Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "0171%07d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 10000000L, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(200).extract().response();
        Long shopId = shopResp.path("id") != null ? shopResp.path("id") : shopResp.path("data.id");
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation returned no ID");
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "চেস্ট",
                  "unit": "inch",
                  "type": "NUMERIC",
                  "suggestiveValues": ["38", "40"],
                  "nsId": "P%03d"
                }
              ]
            }
            """.formatted(timestamp, timestamp, (timestamp % 1000));
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Long itemId = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemId, "Precondition failed: Item creation returned no ID");
        // 4. Create Order
        String phone = "017" + String.format("%08d", timestamp % 100000000L);
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2030-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Handle with care",
                      "clothPhoto": "temp/cloth.jpg",
                      "deliveryDate": "2030-12-31",
                      "makingCharge": 500.00,
                      "measurements": [
                        {
                          "nameEn": "Chest",
                          "nameBn": "চেস্ট",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": 40.0,
                          "nsId": "P001"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, phone, itemId);
        Response orderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        // Extract order item ID
        Long orderItemId = orderResp.path("data.orderItems[0].orderItemId");
        if (orderItemId == null) {
            orderItemId = orderResp.path("data.orderItems[0].id");
        }
        if (orderItemId == null) {
            orderItemId = orderResp.path("data.items[0].id");
        }
        Assert.assertNotNull(orderItemId, "Precondition failed: Order creation returned no order item ID");
        return orderItemId;
    }

    // 113f2a9-TC-019
    @Test
    public void updateStatusFromSewingDoneToPressDone() {
        Long orderItemId = setupOrderAndGetItemId();
        // Transition 1: MEASUREMENT_DONE -> CUTTING_DONE
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"CUTTING_DONE\"}").when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200);
        // Transition 2: CUTTING_DONE -> SEWING_DONE
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"SEWING_DONE\"}").when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200);
        // Assertion for test case: SEWING_DONE -> PRESS_DONE
        String payload = """
            {
              "newStatus": "PRESS_DONE"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(payload).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(200).body("message", equalTo("Order item status updated successfully."));
    }

