    // Helper method to setup shop owner auth
    private String setupShopOwner(String phone, String email) {
        // Request OTP
        Response otpResp = given().queryParam("email", email).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        // Verify OTP
        String verifyBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s"
            }
            """.formatted(phone, otp);
        given().contentType(ContentType.JSON).body(verifyBody).when().post("/api/auth/verify-otp").then().statusCode(200);
        // Set PIN
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(phone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        // Login with PIN
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(phone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String token = loginResp.getHeader("Authorization");
        if (token != null && token.startsWith("Bearer ")) {
            token = token.substring(7);
        }
        return token;
    }

    // Helper to upload base64 photo and get temp URL
    private String uploadPhoto(String token) {
        String dummyBase64 = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
        String body = """
            {
              "photo": "%s"
            }
            """.formatted(dummyBase64);
        Response resp = given().header("Authorization", "Bearer " + token).contentType(ContentType.JSON).body(body).when().post("/api/photos/upload-base64").then().statusCode(200).extract().response();
        return resp.path("url");
    }

    // Helper to create an order and return the first order item ID
    private Long createOrderAndGetOrderItemId(Long shopId, Long itemId, String ownerToken) {
        String photoUrl = uploadPhoto(ownerToken);
        long now = System.currentTimeMillis();
        String customerPhone = "017" + String.format("%08d", now % 100000000L);
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer %d",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2028-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "clothPhoto": "%s",
                      "deliveryDate": "2028-12-31",
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, now, customerPhone, itemId, photoUrl);
        Response resp = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        // Extract order item id from response
        Long orderItemId = resp.path("data.orderItems[0].id");
        if (orderItemId == null) {
            orderItemId = resp.path("data.items[0].id");
        }
        if (orderItemId == null) {
            orderItemId = resp.path("data.orderItems[0].measurementGroups[0].id");
        }
        Assert.assertNotNull(orderItemId, "Precondition failed: Order item ID could not be extracted");
        return orderItemId;
    }

