    private Long createOrderWithMeasurement(String phone, Long itemId, String paramType, Double numericValue, Boolean booleanValue) {
        String valField = numericValue != null ? "\"value\": " + numericValue + "," : "\"value\": null,";
        String boolField = booleanValue != null ? "\"booleanValue\": " + booleanValue + "," : "\"booleanValue\": null,";
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2028-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "temp/cloth.jpg",
                      "makingCharge": 500,
                      "measurements": [
                        {
                          "nameEn": "Length",
                          "nameBn": "দৈর্ঘ্য",
                          "unit": "inch",
                          "type": "%s",
                          %s
                          %s
                          "nsId": "NS01"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, phone, itemId, paramType, valField, boolField);
        Response orderResp = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Integer custIdInt = orderResp.path("data.customerId");
        return custIdInt != null ? custIdInt.longValue() : null;
    }

