    private String createShopOwnerToken(Long shopId) {
        long ts = System.currentTimeMillis();
        String email = "owner" + ts + "@example.com";
        String phone = "017" + String.format("%08d", (int) (ts % 100000000L));
        given().post("/api/auth/request-otp?email=" + email).then().statusCode(200);
        String otpBody = """
            {
              "phoneNumber": "%s",
              "otp": "123456"
            }
            """.formatted(phone);
        given().contentType(ContentType.JSON).body(otpBody).when().post("/api/auth/verify-otp");
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "123456",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(phone);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin");
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(phone);
        Response loginResponse = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String authHeader = loginResponse.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            return authHeader.substring(7);
        }
        return loginResponse.path("data.token");
    }

