    // Helper method to setup an Area, Shop, and obtain a Shop Owner Token
    private ShopOwnerFixture setupShopAndOwner() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area (ADMIN)
        String areaBody = """
            {
              "name": "Test Area %d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdObj = areaResp.path("data.id");
        if (areaIdObj == null)
            areaIdObj = areaResp.path("id");
        Long areaId = Long.valueOf(areaIdObj.toString());
        // 2. Create Shop (ADMIN)
        String shopBody = """
            {
              "shopName": "Shop %d",
              "shopPhone": "017%08d",
              "ownerName": "Owner %d",
              "email": "owner%d@shop.com",
              "address": "123 Test St",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResp.path("data.id");
        if (shopIdObj == null)
            shopIdObj = shopResp.path("id");
        Long shopId = Long.valueOf(shopIdObj.toString());
        // 3. Create Item (ADMIN/Auth)
        String itemBody = """
            {
              "nameEn": "Shirt %d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "বুক",
                  "unit": "inch",
                  "type": "NUMERIC",
                  "nsId": "ns%02d"
                }
              ]
            }
            """.formatted(timestamp, (timestamp / 10) % 100);
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object itemIdObj = itemResp.path("data.id");
        if (itemIdObj == null)
            itemIdObj = itemResp.path("id");
        Long itemId = Long.valueOf(itemIdObj.toString());
        return new ShopOwnerFixture(shopId, itemId, adminToken);
    }

    private static class ShopOwnerFixture {
        final String token;


        final Long shopId;

        final Long itemId;

        ShopOwnerFixture(Long shopId, Long itemId, String token) {
            this.shopId = shopId;
            this.itemId = itemId;
            this.token = token;
        }
    }

