    // 0399124-TC-020
    @Test
    public void attemptToUpdateOrderStatusWithAnInvalidStatusValue() {
        // Login as ADMIN to obtain admin token
        String adminSignIn = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response adminLoginResp = given().contentType(ContentType.JSON).body(adminSignIn).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String adminToken = adminLoginResp.getHeader("Authorization");
        if (adminToken != null && adminToken.startsWith("Bearer ")) {
            adminToken = adminToken.substring(7);
        }
        // Step 1: Create Area as ADMIN
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Object areaIdObj = areaResp.path("data.id");
        Long areaId = areaIdObj != null ? Long.valueOf(areaIdObj.toString()) : Long.valueOf(areaResp.path("id").toString());
        // Step 2: Create Shop under Area as ADMIN
        String shopBody = """
            {
              "shopName": "TestShop_%d",
              "shopPhone": "01700000000",
              "ownerName": "ShopOwner",
              "email": "owner_%d@example.com",
              "address": "123 Main St",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis(), areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(200).extract().response();
        Object shopIdObj = shopResp.path("data.id");
        Long shopId = shopIdObj != null ? Long.valueOf(shopIdObj.toString()) : Long.valueOf(shopResp.path("id").toString());
        // Step 3: Create Item as ADMIN
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Object itemIdObj = itemResp.path("data.id");
        Long itemId = itemIdObj != null ? Long.valueOf(itemIdObj.toString()) : Long.valueOf(itemResp.path("id").toString());
        // Step 4: Create Order as ADMIN (ADMIN bypasses ownership check)
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "01711111111",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2030-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "clothPhoto": "http://example.com/photo.jpg",
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response orderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Object orderItemIdObj = orderResp.path("data.orderItems[0].id");
        if (orderItemIdObj == null) {
            orderItemIdObj = orderResp.path("data.items[0].id");
        }
        Assert.assertNotNull(orderItemIdObj, "Precondition failed: Order item ID could not be extracted");
        Long orderItemId = Long.valueOf(orderItemIdObj.toString());
        // Step 5: Send invalid status update request
        String invalidStatusBody = """
            {
              "newStatus": "INVALID_STATUS"
            }
            """;
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(invalidStatusBody).when().put("/api/orders/items/{orderItemId}/status", orderItemId).then().statusCode(anyOf(is(400), is(422), is(500)));
    }

