    private String getAdminToken5() {
        String body = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response response = given().contentType(ContentType.JSON).body(body).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String header = response.getHeader("Authorization");
        if (header != null && header.startsWith("Bearer ")) {
            return header.substring(7);
        }
        return "";
    }

