    // 3c1bbe1-TC-003 - Verify that order IDs are generated sequentially and uniquely for the same shop on the same day
    @Test
    public void testSequentialOrderIdGeneration() {
        Long areaId = createAreaHelper();
        Long shopId = createShopHelper(areaId);
        Long itemId = createItemHelper();
        String today = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
        String deliveryDateStr = LocalDate.now().plusDays(5).format(DateTimeFormatter.ISO_LOCAL_DATE);
        String orderPayload1 = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "None",
                      "clothPhoto": "http://localhost/temp/cloth.jpg",
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, deliveryDateStr, itemId);
        Response response1 = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderPayload1).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId1 = response1.path("data.orderId");
        Assert.assertNotNull(orderId1, "First created order returned no orderId");
        String expectedPrefix1 = shopId + "-" + today + "-";
        Assert.assertTrue(orderId1.startsWith(expectedPrefix1), "Order ID should start with shop and date sequence prefix. Got: " + orderId1);
        String orderPayload2 = """
            {
              "shopId": %d,
              "customerName": "Jane Doe",
              "customerPhone": "01712345679",
              "customerGender": "FEMALE",
              "paidAmount": 200.00,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "None",
                      "clothPhoto": "http://localhost/temp/cloth2.jpg",
                      "makingCharge": 600.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, deliveryDateStr, itemId);
        Response response2 = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderPayload2).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId2 = response2.path("data.orderId");
        Assert.assertNotNull(orderId2, "Second created order returned no orderId");
        Assert.assertNotEquals(orderId1, orderId2, "Order IDs must be unique");
        Assert.assertTrue(orderId2.startsWith(expectedPrefix1), "Second Order ID should share the same shop and date prefix. Got: " + orderId2);
    }

