    // Helper method to create an order and return array [numericId (Long), businessOrderId (String)]
    private Object[] createOrderForShop(Long shopId, Long itemId) {
        String phone = "017" + String.format("%08d", (int) (Math.random() * 100000000));
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2030-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Handle with care",
                      "clothPhoto": "temp-cloth.jpg",
                      "deliveryDate": "2030-12-31",
                      "makingCharge": 500.00,
                      "measurements": [
                        {
                          "nameEn": "Chest",
                          "nameBn": "বুক",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": "40",
                          "nsId": "P001"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, phone, itemId);
        Response response = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Integer numId = response.path("data.id");
        String orderCode = response.path("data.orderId");
        Assert.assertNotNull(numId, "Precondition failed: order creation returned null numeric id");
        return new Object[] { numId.longValue(), orderCode };
    }

    // 3c1bbe1-TC-012
    @Test
    public void verifyQrCodeGenerationAuthorizationEnforcement() {
        Long areaId = createArea21();
        Long shopAId = createShop17(areaId);
        Long shopBId = createShop17(areaId);
        Long itemId = createItem27();
        Object[] orderDataA = createOrderForShop(shopAId, itemId);
        Long orderAId = (Long) orderDataA[0];
        // Attempt to access Order A's QR code (User B / unauthenticated or unauthorized context)
        // Since order security uses @PreAuthorize("@shopSecurity.ownsOrder(authentication, #orderId)"),
        // using adminToken will pass, but here we don't pass owner authentication for Shop A
        // Calling endpoint with a request that lacks authorization for Shop A
        given().contentType(ContentType.JSON).when().get("/api/orders/{orderId}/qrcode", orderAId).then().statusCode(anyOf(is(401), is(403)));
    }

