    // 0f2b8f4-TC-005 - Verify that order update with malicious base64 image data is rejected to prevent injection
    @Test
    public void testOrderUpdateWithMaliciousBase64ImageIsRejected() {
        Long areaId = createArea22();
        Long shopId = createShop18(areaId);
        Long itemId = createItem28();
        String createOrderPayload = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 100.0,
              "deliveryDate": "2025-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500.0,
                      "clothPhoto": "http://example.com/temp-cloth.jpg",
                      "measurements": [
                        {
                          "nameEn": "Chest",
                          "nameBn": "চেস্ট",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": "40",
                          "nsId": "P001"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        Response createOrderRes = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(createOrderPayload).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object orderIdObj = createOrderRes.path("data.id") != null ? createOrderRes.path("data.id") : createOrderRes.path("id");
        Assert.assertNotNull(orderIdObj, "Precondition failed: Order creation returned no numeric ID");
        Long orderId = Long.valueOf(orderIdObj.toString());
        String maliciousUpdatePayload = """
            {
              "shopId": %d,
              "customerName": "Test Customer",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "customerPhoto": "data:text/html;base64,PHNjcmlwdD5hbGVydCgnWFNTJyk8L3NjcmlwdD4=",
              "paidAmount": 100.0,
              "deliveryDate": "2025-12-31",
              "items": []
            }
            """.formatted(shopId);
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(maliciousUpdatePayload).when().put("/api/orders/{orderId}", orderId).then().statusCode(anyOf(is(400), is(422)));
    }

