        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Integer itemId = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Assert.assertNotNull(itemId, "Precondition failed: Item ID is null");
        // Step 2: Construct payload with oversized base64 image (10MB+ string)
