    // e2af361-TC-028 - Verify that file upload endpoint enforces rate limiting to prevent abuse
    @Test
    public void testFileUploadRateLimiting() {
        Assert.assertNotNull(adminToken, "Precondition failed: Admin token not retrieved");
        // Rapidly send requests to trigger rate limiting
        int hitRateLimitStatus = -1;
        byte[] dummyFileContent = "dummy image content".getBytes();
        for (int i = 0; i < 20; i++) {
            Response response = given().header("Authorization", "Bearer " + adminToken).multiPart("file", "test.jpg", dummyFileContent, "image/jpeg").when().post("/api/photos/upload");
            if (response.getStatusCode() == 429) {
                hitRateLimitStatus = 429;
                break;
            }
        }
        Assert.assertEquals(hitRateLimitStatus, 429, "Expected HTTP status 429 (Too Many Requests) when exceeding rate limit");
    }

    // e2af361-TC-029
