    // 92528b6-TC-001
    @Test
    public void verifyOrderIdGenerationForDifferentShops() {
        Long areaId = createArea23();
        Long shopId1 = createShop19(areaId);
        Long shopId2 = createShop19(areaId);
        Long itemId = createItem29();
        String today = LocalDate.now().format(DateTimeFormatter.ISO_LOCAL_DATE);
        String formattedDate = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
        String orderPayload1 = """
            {
              "shopId": %d,
              "customerName": "Jane Smith",
              "customerPhone": "01812345678",
              "customerGender": "FEMALE",
              "paidAmount": 100,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Salwar Kameez",
                      "clothPhoto": "http://minio/temp/cloth1.jpg",
                      "deliveryDate": "%s",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId1, today, itemId, today);
        Response response1 = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderPayload1).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderIdCode1 = response1.path("data.orderId");
        Assert.assertNotNull(orderIdCode1, "Order 1 ID code should not be null");
        Assert.assertTrue(orderIdCode1.startsWith(shopId1 + "-" + formattedDate), "Order ID 1 should start with shopId1 and date pattern. Got: " + orderIdCode1);
        String orderPayload2 = """
            {
              "shopId": %d,
              "customerName": "Jane Smith",
              "customerPhone": "01812345678",
              "customerGender": "FEMALE",
              "paidAmount": 100,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Salwar Kameez",
                      "clothPhoto": "http://minio/temp/cloth2.jpg",
                      "deliveryDate": "%s",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId2, today, itemId, today);
        Response response2 = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderPayload2).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderIdCode2 = response2.path("data.orderId");
        Assert.assertNotNull(orderIdCode2, "Order 2 ID code should not be null");
        Assert.assertTrue(orderIdCode2.startsWith(shopId2 + "-" + formattedDate), "Order ID 2 should start with shopId2 and date pattern. Got: " + orderIdCode2);
        Assert.assertNotEquals(orderIdCode1, orderIdCode2, "Order IDs across different shops should be unique");
    }

