    // 92528b6-TC-012
    @Test
    public void generateOrderIdForShopWithExistingOrdersOnSameDate() {
        Long areaId = createArea25();
        Assert.assertNotNull(areaId, "Precondition failed: Area creation failed");
        Long shopId = createShop21(areaId);
        Assert.assertNotNull(shopId, "Precondition failed: Shop creation failed");
        Long itemId = createItem31();
        Assert.assertNotNull(itemId, "Precondition failed: Item creation failed");
        String today = LocalDate.now().format(DateTimeFormatter.ISO_LOCAL_DATE);
        String todayCompact = LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
        // Create 1st order for the shop
        long ts = System.currentTimeMillis();
        String orderBody1 = """
            {
              "shopId": %d,
              "customerName": "Customer 1",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 500,
                      "clothPhoto": "http://example.com/temp/cloth.jpg",
                      "deliveryDate": "%s",
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, today, itemId, today);
        Response order1Res = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody1).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId1 = order1Res.path("data.orderId");
        Assert.assertNotNull(orderId1, "First created order should have an orderId");
        Assert.assertTrue(orderId1.endsWith("-0001"), "First order should end with sequence -0001, got: " + orderId1);
        // Create 2nd order for the same shop
        String orderBody2 = """
            {
              "shopId": %d,
              "customerName": "Customer 2",
              "customerPhone": "01812345678",
              "customerGender": "FEMALE",
              "paidAmount": 50,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "makingCharge": 300,
                      "clothPhoto": "http://example.com/temp/cloth2.jpg",
                      "deliveryDate": "%s",
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, today, itemId, today);
        Response order2Res = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody2).when().post("/api/orders").then().statusCode(200).extract().response();
        String orderId2 = order2Res.path("data.orderId");
        Assert.assertNotNull(orderId2, "Second created order should have an orderId");
        String expectedPrefix = shopId + "-" + todayCompact + "-";
        Assert.assertTrue(orderId2.startsWith(expectedPrefix), "Order ID should start with " + expectedPrefix + ", got: " + orderId2);
        Assert.assertTrue(orderId2.endsWith("-0002"), "Second order sequence should increment by 1 (-0002), got: " + orderId2);
    }

