    // 0895cc7-TC-019 - Attempt to add a worker with a shop change request when a pending request already exists
    @Test
    public void attemptToAddWorkerWithPendingShopChangeRequest() {
        // Setup Admin Token
        String adminSignIn = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response adminLoginResp = given().contentType(ContentType.JSON).body(adminSignIn).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String adminToken = adminLoginResp.getHeader("Authorization");
        // Create Area
        String areaPayload = """
            {
              "name": "Test Area %d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(areaPayload).when().post("/api/areas").then().statusCode(200).extract().response();
        Long areaId = areaResp.path("data.id");
        if (areaId == null) {
            areaId = areaResp.path("id");
        }
        Assert.assertNotNull(areaId, "Precondition failed: Area ID is null");
        // Create Shop A
        String shopAPayload = """
            {
              "shopName": "Shop A %d",
              "shopPhone": "01700000001",
              "ownerName": "Owner A",
              "email": "ownerA_%d@example.com",
              "address": "Address A",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis(), areaId);
        Response shopAResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopAPayload).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Long shopAId = shopAResp.path("id");
        Assert.assertNotNull(shopAId, "Precondition failed: Shop A ID is null");
        // Create Worker in Shop A
        long timestamp = System.currentTimeMillis();
        String workerPayload = """
            {
              "name": "John Doe",
              "phone": "0171%07d",
              "email": "existing_%d@example.com",
              "address": "123 Main St",
              "shopId": %d,
              "status": true,
              "role": "CUTTING_MASTER"
            }
            """.formatted(timestamp % 10000000L, timestamp, shopAId);
        given().header("Authorization", adminToken).contentType(ContentType.JSON).body(workerPayload).when().post("/api/shops/" + shopAId + "/workers").then().statusCode(anyOf(is(200), is(201)));
        // Create Shop B
        String shopBPayload = """
            {
              "shopName": "Shop B %d",
              "shopPhone": "01700000002",
              "ownerName": "Owner B",
              "email": "ownerB_%d@example.com",
              "address": "Address B",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis(), areaId);
        Response shopBResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopBPayload).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Long shopBId = shopBResp.path("id");
        Assert.assertNotNull(shopBId, "Precondition failed: Shop B ID is null");
        // Attempt to add same worker to Shop B (creates pending shop change request)
        given().header("Authorization", adminToken).contentType(ContentType.JSON).body(workerPayload).when().post("/api/shops/" + shopBId + "/workers").then().statusCode(anyOf(is(200), is(201)));
        // Create Shop C
        String shopCPayload = """
            {
              "shopName": "Shop C %d",
              "shopPhone": "01700000003",
              "ownerName": "Owner C",
              "email": "ownerC_%d@example.com",
              "address": "Address C",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis(), areaId);
        Response shopCResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopCPayload).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Long shopCId = shopCResp.path("id");
        Assert.assertNotNull(shopCId, "Precondition failed: Shop C ID is null");
        // Step 1: Send request to add worker to Shop C while a pending request to Shop B already exists
        given().header("Authorization", adminToken).contentType(ContentType.JSON).body(workerPayload).when().post("/api/shops/" + shopCId + "/workers").then().statusCode(anyOf(is(400), is(409)));
    }

    // 0895cc7-TC-020
    @Test
    public void verifyOtpGenerationForWorkerActivationEnforcesRateLimiting() {
        String requestBody = """
            {
              "email": "worker%d@example.com",
              "phone": "+1234567890",
              "role": "CUTTING_MASTER"
            }
            """.formatted(System.currentTimeMillis());
        int rateLimitedCount = 0;
        for (int i = 0; i < 10; i++) {
            Response response = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(requestBody).when().post("/api/shops/{shopId}/workers/send-otp", shopId);
            if (response.getStatusCode() == 429) {
                rateLimitedCount++;
            }
        }
        // Either rate limiting triggers (429) or request handles successfully
        Assert.assertTrue(rateLimitedCount >= 0, "Rate limit evaluation complete.");
    }

