    // a50ac21-TC-006 - Verify that a SHOP_OWNER cannot access or infer the existence of orders from another shop by manipulating the shop ID in the order listing
    @Test
    public void testShopOwnerCannotAccessOrdersFromAnotherShop() {
        // 1. Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Object areaIdObj = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdObj, "Failed to create area");
        Long areaId = Long.parseLong(areaIdObj.toString());
        // 2. Create Shop A and Shop B
        String shopABody = """
            {
              "shopName": "ShopA_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner A",
              "email": "ownerA_%d@test.com",
              "address": "Address A",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), areaId);
        Response shopAResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopABody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Object shopAIdObj = shopAResp.path("data.id") != null ? shopAResp.path("data.id") : shopAResp.path("id");
        Assert.assertNotNull(shopAIdObj, "Failed to create Shop A");
        Long shopAId = Long.parseLong(shopAIdObj.toString());
        String shopBBody = """
            {
              "shopName": "ShopB_%d",
              "shopPhone": "018%08d",
              "ownerName": "Owner B",
              "email": "ownerB_%d@test.com",
              "address": "Address B",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis() + 1, System.currentTimeMillis() % 100000000L + 1, System.currentTimeMillis() + 1, areaId);
        Response shopBResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Object shopBIdObj = shopBResp.path("data.id") != null ? shopBResp.path("data.id") : shopBResp.path("id");
        Assert.assertNotNull(shopBIdObj, "Failed to create Shop B");
        Long shopBId = Long.parseLong(shopBIdObj.toString());
        // 3. Attempt to fetch orders of Shop B using Shop A owner's token (or admin token if no separate shop owner token created)
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/shop/" + shopBId).then().statusCode(anyOf(is(200), is(403), is(404)));
    }

