    private String getAdminToken6() {
        String signInBody = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response response = given().contentType(ContentType.JSON).body(signInBody).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String authHeader = response.getHeader("Authorization");
        if (authHeader != null && !authHeader.isBlank()) {
            return authHeader.startsWith("Bearer ") ? authHeader : "Bearer " + authHeader;
        }
        String token = response.path("data.accessToken");
        return "Bearer " + token;
    }

