    // dbc9d14-TC-002
    @Test
    public void retrieveOrderDetailsAndVerifyFinancialSummary() {
        String orderPayload = """
            {
              "shopId": %d,
              "customerName": "Jane Doe",
              "customerPhone": "01811112233",
              "customerGender": "FEMALE",
              "paidAmount": 500.00,
              "deliveryDate": "2026-05-20",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "http://localhost/temp/cloth.jpg",
                      "makingCharge": 1500.00,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, itemId);
        String orderCode = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(orderPayload).when().post("/api/orders").then().statusCode(200).extract().path("data.orderId");
        Assert.assertNotNull(orderCode, "Precondition failed: Order creation returned no orderId");
        Response getResp = given().header("Authorization", "Bearer " + ownerToken).when().get("/api/orders/{orderId}", orderCode).then().statusCode(200).body("status", equalTo("success")).extract().response();
        Number totalAmount = getResp.path("data.totalAmount");
        Number paidAmount = getResp.path("data.paidAmount");
        Number dueAmount = getResp.path("data.dueAmount");
        Assert.assertEquals(totalAmount.doubleValue(), 1500.00, 0.01, "totalAmount match");
        Assert.assertEquals(paidAmount.doubleValue(), 500.00, 0.01, "paidAmount match");
        Assert.assertEquals(dueAmount.doubleValue(), 1000.00, 0.01, "dueAmount match");
    }

