        Response createOrderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderReqBody).when().post("/api/orders").then().statusCode(200).body("status", equalTo("success")).extract().response();
        String orderBusinessCode = createOrderResp.path("data.orderId");
        Assert.assertNotNull(orderBusinessCode, "Order creation did not return business orderId");
