    // 9cb3615-TC-029 - Verify that retrieving workers by shop ID returns correct shopId and areaId context for authorized users
    @Test
    public void testGetWorkersByShopId() {
        // 1. Get Admin Token
        String adminSignIn = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response loginResp = given().contentType(ContentType.JSON).body(adminSignIn).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String adminToken = loginResp.getHeader("Authorization");
        if (adminToken == null || adminToken.isEmpty()) {
            adminToken = "Bearer " + loginResp.path("data.token");
        }
        // 2. Create Area
        long timestamp = System.currentTimeMillis();
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdObj = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Assert.assertNotNull(areaIdObj, "Failed to create precondition area");
        Long areaId = Long.parseLong(areaIdObj.toString());
        // 3. Create Shop
        String shopBody = """
            {
              "shopName": "TestShop_%d",
              "shopPhone": "01711%06d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "123 Test Street",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 1000000, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Assert.assertNotNull(shopIdObj, "Failed to create precondition shop");
        Long shopId = Long.parseLong(shopIdObj.toString());
        // 4. Create Worker in Shop
        String workerBody = """
            {
              "name": "Worker_%d",
              "phone": "01811%06d",
              "email": "worker_%d@example.com",
              "address": "456 Worker St",
              "shopId": %d,
              "status": true,
              "role": "CUTTING_MASTER"
            }
            """.formatted(timestamp, timestamp % 1000000, timestamp, shopId);
        given().header("Authorization", adminToken).contentType(ContentType.JSON).body(workerBody).when().post("/api/shops/" + shopId + "/workers").then().statusCode(anyOf(is(200), is(201)));
        // 5. Retrieve Workers for Shop
        given().header("Authorization", adminToken).when().get("/api/shops/" + shopId + "/workers").then().statusCode(200).body("status", equalTo("success")).body("data.content", not(empty()));
    }

