    // d743d3c-TC-004
    @Test
    public void verifyNonExistentFileProxyDoesNotLeakCredentials() {
        Response response = given().when().get("/invalid-folder/non-existent-file.jpg").then().statusCode(404).extract().response();
        String responseBody = response.asString().toLowerCase();
        Assert.assertFalse(responseBody.contains("secret"), "Response body should not contain secret information");
        Assert.assertFalse(responseBody.contains("accesskey"), "Response body should not leak access keys");
        Assert.assertFalse(responseBody.contains("minio"), "Response body should not leak internal storage service details");
    }

