    // 5437faa-TC-001
    @Test
    public void verifyOrdersForShopAreDisplayedInDescendingOrder() {
        Long order1 = createOrderHelper("Customer One", "01711%06d".formatted(System.currentTimeMillis() % 1000000));
        Long order2 = createOrderHelper("Customer Two", "01712%06d".formatted(System.currentTimeMillis() % 1000000));
        Long order3 = createOrderHelper("Customer Three", "01713%06d".formatted(System.currentTimeMillis() % 1000000));
        Response response = given().header("Authorization", "Bearer " + shopOwnerToken).queryParam("page", 0).queryParam("limit", 10).when().get("/api/orders/shop/{shopId}", shopId).then().statusCode(200).extract().response();
        List<Integer> orderIds = response.path("data.content.id");
        Assert.assertNotNull(orderIds, "Order list should not be null");
        Assert.assertTrue(orderIds.size() >= 3, "At least 3 orders should be retrieved");
        // Assert descending order (newest first)
        for (int i = 0; i < orderIds.size() - 1; i++) {
            Assert.assertTrue(orderIds.get(i) > orderIds.get(i + 1), "Orders are not sorted in descending order by ID: " + orderIds.get(i) + " vs " + orderIds.get(i + 1));
        }
    }

