    private String getAdminToken7() {
        String signInBody = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response response = given().contentType(ContentType.JSON).body(signInBody).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String token = response.getHeader("Authorization");
        if (token != null && token.startsWith("Bearer ")) {
            return token;
        }
        return "Bearer " + token;
    }

