    // 0b31caa-TC-003
    @Test
    public void makePaymentOneCentAboveRemainingDueAmount2() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area as ADMIN
        String areaBody = """
            {
              "name": "TestArea_%d"
            }
            """.formatted(timestamp);
        Response areaResponse = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Object areaIdObj = areaResponse.path("data.id");
        Assert.assertNotNull(areaIdObj, "Precondition failed: Area ID is null");
        Long areaId = Long.valueOf(areaIdObj.toString());
        // 2. Create Shop as ADMIN
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@example.com",
              "address": "123 Main St",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResponse = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Object shopIdObj = shopResponse.path("id");
        if (shopIdObj == null) {
            shopIdObj = shopResponse.path("data.id");
        }
        Assert.assertNotNull(shopIdObj, "Precondition failed: Shop ID is null");
        Long shopId = Long.valueOf(shopIdObj.toString());
        // 3. Create Item as ADMIN
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Chest",
                  "nameBn": "চেস্ট",
                  "unit": "inch",
                  "type": "NUMERIC",
                  "suggestiveValues": ["38", "40"],
                  "nsId": "C%03d"
                }
              ]
            }
            """.formatted(timestamp, timestamp, (timestamp % 1000));
        Response itemResponse = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Object itemIdObj = itemResponse.path("data.id");
        if (itemIdObj == null) {
            itemIdObj = itemResponse.path("id");
        }
        Assert.assertNotNull(itemIdObj, "Precondition failed: Item ID is null");
        Long itemId = Long.valueOf(itemIdObj.toString());
        // 4. Create Order as ADMIN (totalAmount = 500.00, paidAmount = 200.00)
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer_%d",
              "customerPhone": "017%08d",
              "customerGender": "MALE",
              "paidAmount": 200.00,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "http://localhost:8083/temp/cloth.jpg",
                      "deliveryDate": "2026-12-31",
                      "makingCharge": 500.00,
                      "measurements": [
                        {
                          "nameEn": "Chest",
                          "nameBn": "চেস্ট",
                          "unit": "inch",
                          "type": "NUMERIC",
                          "value": "40",
                          "nsId": "C%03d"
                        }
                      ]
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp, timestamp % 100000000L, itemId, (timestamp % 1000));
        Response createOrderResponse = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Object orderIdObj = createOrderResponse.path("data.id");
        Assert.assertNotNull(orderIdObj, "Precondition failed: Order ID is null");
        Long numericOrderId = Long.valueOf(orderIdObj.toString());
        // 5. Submit payment exceeding due amount (300.01)
        String paymentRequest = """
            {
              "paymentAmount": 300.01
            }
            """;
        Response paymentResponse = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(paymentRequest).when().post("/api/orders/" + numericOrderId + "/pay").then().statusCode(200).extract().response();
        // Assert message
        String message = paymentResponse.path("message");
        if (message == null) {
            message = paymentResponse.asString();
        }
        Assert.assertTrue(message.contains("Payment exceeds total order amount") || message.contains("exceeds"), "Expected overpayment error message but got: " + message);
        // Assert balances remained unchanged
        Number totalAmount = paymentResponse.path("totalAmount");
        Number paidAmount = paymentResponse.path("paidAmount");
        Number dueAmount = paymentResponse.path("dueAmount");
        if (totalAmount != null) {
            Assert.assertEquals(totalAmount.doubleValue(), 500.00, 0.001);
        }
        if (paidAmount != null) {
            Assert.assertEquals(paidAmount.doubleValue(), 200.00, 0.001);
        }
        if (dueAmount != null) {
            Assert.assertEquals(dueAmount.doubleValue(), 300.00, 0.001);
        }
    }

