    // 06d96c2-TC-009 - Create an order with exactly one measurement group containing exactly one non-blank cloth photo (single-element collection boundary)
    @Test
    public void testCreateOrderWithSingleClothPhotoBoundary() {
        long timestamp = System.currentTimeMillis();
        // 1. Setup Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object areaIdObj = areaResp.path("data.id") != null ? areaResp.path("data.id") : areaResp.path("id");
        Long areaId = Long.valueOf(areaIdObj.toString());
        // 2. Setup Shop
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "017%08d",
              "ownerName": "Owner_%d",
              "email": "owner_%d@test.com",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, timestamp % 100000000L, timestamp, timestamp, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object shopIdObj = shopResp.path("data.id") != null ? shopResp.path("data.id") : shopResp.path("id");
        Long shopId = Long.valueOf(shopIdObj.toString());
        // 3. Setup Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট_%d",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Length",
                  "nameBn": "দৈর্ঘ্য",
                  "unit": "inch",
                  "type": "NUMERIC",
                  "nsId": "L%d"
                }
              ]
            }
            """.formatted(timestamp, timestamp, timestamp % 1000);
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Object itemIdObj = itemResp.path("data.id") != null ? itemResp.path("data.id") : itemResp.path("id");
        Long itemId = Long.valueOf(itemIdObj.toString());
        // 4. Create Order
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer_%d",
              "customerPhone": "018%08d",
              "customerGender": "MALE",
              "paidAmount": 100,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Handle carefully",
                      "clothPhoto": "only-photo.jpg",
                      "deliveryDate": "2026-12-31",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, timestamp, timestamp % 100000000L, itemId);
        Response createOrderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        String businessCode = createOrderResp.path("data.orderId");
        Assert.assertNotNull(businessCode, "Precondition failed: orderId business code was not returned");
        // 5. Verify Order Fetch
        given().header("Authorization", "Bearer " + adminToken).when().get("/api/orders/{orderId}", businessCode).then().statusCode(200).body("data.orderItems[0].measurementGroups[0].clothPhoto", notNullValue());
    }

