    // Helper method to create area, shop, worker/owner context if needed
    private String getShopOwnerToken() {
        long timestamp = System.currentTimeMillis();
        // 1. Create Area as Admin
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(timestamp);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Integer areaId = areaResp.path("data.id");
        if (areaId == null) {
            areaId = areaResp.path("id");
        }
        // 2. Create Shop as Admin
        String shopEmail = "owner_%d@example.com".formatted(timestamp);
        String shopPhone = "017%08d".formatted(timestamp % 100000000L);
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "%s",
              "ownerName": "Owner_%d",
              "email": "%s",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, shopPhone, timestamp, shopEmail, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Integer shopId = shopResp.path("data.id");
        if (shopId == null) {
            shopId = shopResp.path("id");
        }
        // 3. Register Shop Owner Worker and set PIN
        String workerPhone = shopPhone;
        String workerBody = """
            {
              "name": "OwnerWorker_%d",
              "phone": "%s",
              "email": "%s",
              "address": "Owner Address",
              "shopId": %d,
              "status": true,
              "role": "CUTTING_MASTER"
            }
            """.formatted(timestamp, workerPhone, shopEmail, shopId);
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(workerBody).when().post("/api/shops/" + shopId + "/workers").then().statusCode(200);
        // Request OTP for the email
        Response otpResp = given().when().post("/api/auth/request-otp?email=" + shopEmail).then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        // Verify OTP
        String verifyOtpBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s"
            }
            """.formatted(workerPhone, otp);
        given().contentType(ContentType.JSON).body(verifyOtpBody).when().post("/api/auth/verify-otp").then().statusCode(200);
        // Set PIN
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "ConfirmPin": "1234"
            }
            """.formatted(workerPhone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        // Login with PIN
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(workerPhone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String ownerToken = loginResp.getHeader("Authorization");
        if (ownerToken != null && ownerToken.startsWith("Bearer ")) {
            ownerToken = ownerToken.substring(7);
        }
        return ownerToken;
    }

