    // 49c37e5-TC-001
    @Test
    public void verifyPaginationWorksCorrectlyWithNewestOrdersAppearingOnFirstPage() {
        Long shopId = createAreaAndShop8();
        Long itemId = createItem42();
        // Create multiple orders (e.g., 6) to test pagination with size 5
        for (int i = 0; i < 6; i++) {
            String orderBody = """
                {
                  "shopId": %d,
                  "customerName": "Customer %d",
                  "customerPhone": "01712%06d",
                  "customerGender": "MALE",
                  "paidAmount": 100.00,
                  "trialDate": "2026-03-01",
                  "deliveryDate": "2026-03-05",
                  "items": [
                    {
                      "itemId": %d,
                      "measurementGroups": [
                        {
                          "specialInstruction": "Handle with care",
                          "clothPhoto": "http://example.com/temp/photo%d.jpg",
                          "deliveryDate": "2026-03-05",
                          "makingCharge": 500.00,
                          "measurements": []
                        }
                      ]
                    }
                  ]
                }
                """.formatted(shopId, i, (int) (Math.random() * 1000000), itemId, i);
            given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200);
        }
        // Page 0 with limit 5
        given().header("Authorization", "Bearer " + adminToken).queryParam("page", 0).queryParam("limit", 5).when().get("/api/orders/shop/{shopId}", shopId).then().statusCode(200).body("status", equalTo("success")).body("data.content", hasSize(5)).body("meta.totalElements", equalTo(6)).body("meta.totalPages", equalTo(2));
        // Page 1 with limit 5
        given().header("Authorization", "Bearer " + adminToken).queryParam("page", 1).queryParam("limit", 5).when().get("/api/orders/shop/{shopId}", shopId).then().statusCode(200).body("status", equalTo("success")).body("data.content", hasSize(1));
    }

