    // 49c37e5-TC-010
    @Test
    public void verifyOrderListingForShopSortedByCreationDateDescending() {
        String phone1 = "015" + String.format("%08d", System.currentTimeMillis() % 100000000L);
        String phone2 = "016" + String.format("%08d", System.currentTimeMillis() % 100000000L);
        Long firstCreatedId = createOrderHelper2(phone1, "First Customer");
        try {
            Thread.sleep(100);
        } catch (InterruptedException ignored) {
        }
        Long secondCreatedId = createOrderHelper2(phone2, "Second Customer");
        Assert.assertNotNull(firstCreatedId, "Precondition failed: first order failed");
        Assert.assertNotNull(secondCreatedId, "Precondition failed: second order failed");
        Response response = given().header("Authorization", "Bearer " + shopOwnerToken).when().get("/api/orders/shop/{shopId}", shopId).then().statusCode(200).body("status", equalTo("success")).extract().response();
        List<Integer> ids = response.path("data.content.id");
        Assert.assertNotNull(ids, "Order IDs list should not be null");
        Assert.assertTrue(ids.size() >= 2, "Order list should contain at least 2 orders");
        int indexFirst = ids.indexOf(firstCreatedId.intValue());
        int indexSecond = ids.indexOf(secondCreatedId.intValue());
        Assert.assertTrue(indexFirst != -1 && indexSecond != -1, "Both created orders should be present in the listing");
        Assert.assertTrue(indexSecond < indexFirst, "Most recently created order (secondCreatedId) should appear before older order (firstCreatedId)");
    }

    // 12878fa-TC-001
    @Test
    public void emptyShopReturnsZeroForMonetarySummaryFields() {
        // Step 1: Sign in as admin to set up an area and shop
        String adminSignInBody = """
            {
              "username": "admin",
              "password": "admin"
            }
            """;
        Response adminSignInResp = given().contentType(ContentType.JSON).body(adminSignInBody).when().post("/api/auth/signin").then().statusCode(200).extract().response();
        String adminToken = adminSignInResp.getHeader("Authorization");
        Assert.assertNotNull(adminToken, "Admin sign-in failed to return Authorization header");
        // Step 2: Create Area
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long areaId = areaResp.path("data.id") != null ? areaResp.jsonPath().getLong("data.id") : areaResp.jsonPath().getLong("id");
        Assert.assertNotNull(areaId, "Precondition failed: Area creation returned no ID");
        // Step 3: Create Shop
        long timestamp = System.currentTimeMillis();
        String shopPhone = "017" + String.format("%08d", (int) (timestamp % 100000000L));
        String ownerEmail = "owner" + timestamp + "@example.com";
        String shopBody = """
            {
              "shopName": "Shop_%d",
              "shopPhone": "%s",
              "ownerName": "Owner_%d",
              "email": "%s",
              "address": "123 Main Street",
              "areaId": %d,
              "status": true
            }
            """.formatted(timestamp, shopPhone, timestamp, ownerEmail, areaId);
        given().header("Authorization", adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/{areaId}/shops", areaId).then().statusCode(anyOf(is(200), is(201)));
        // Step 4: Request OTP & Set PIN for Shop Owner
        Response otpResp = given().queryParam("email", ownerEmail).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        Assert.assertNotNull(otp, "Precondition failed: OTP request returned null OTP");
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(shopPhone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        // Step 5: Login as Shop Owner to obtain SHOP_OWNER JWT
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(shopPhone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String ownerToken = loginResp.getHeader("Authorization");
        Assert.assertNotNull(ownerToken, "Shop owner login failed to return Authorization header");
        // Step 6: Call Dashboard Summary endpoint and assert monetary fields equal 0
        Response summaryResp = given().header("Authorization", ownerToken).when().get("/api/dashboard/summary").then().statusCode(200).body("status", equalTo("success")).extract().response();
        Number earningToday = summaryResp.path("data.earningToday");
        Number totalDue = summaryResp.path("data.totalDue");
        Number totalEarning = summaryResp.path("data.totalEarning");
        Number totalOrderAmount = summaryResp.path("data.totalOrderAmount");
        Number earningThisMonth = summaryResp.path("data.earningThisMonth");
        Assert.assertNotNull(earningToday, "earningToday should not be null");
        Assert.assertEquals(earningToday.doubleValue(), 0.0, 0.001, "earningToday should return 0.00 instead of null");
        Assert.assertNotNull(totalDue, "totalDue should not be null");
        Assert.assertEquals(totalDue.doubleValue(), 0.0, 0.001, "totalDue should return 0.00 instead of null");
        Assert.assertNotNull(totalEarning, "totalEarning should not be null");
        Assert.assertEquals(totalEarning.doubleValue(), 0.0, 0.001, "totalEarning should return 0.00 instead of null");
        Assert.assertNotNull(totalOrderAmount, "totalOrderAmount should not be null");
        Assert.assertEquals(totalOrderAmount.doubleValue(), 0.0, 0.001, "totalOrderAmount should return 0.00 instead of null");
        Assert.assertNotNull(earningThisMonth, "earningThisMonth should not be null");
        Assert.assertEquals(earningThisMonth.doubleValue(), 0.0, 0.001, "earningThisMonth should return 0.00 instead of null");
    }

