    // f8d06b7-TC-005 - Update item with matching parameter nameEn to verify nsId preservation boundary
    @Test
    public void updateItemWithMatchingParameterPreservesNsId() {
        // Setup: Create an item with parameter nameEn 'Waist' and initial nsId 'AB12'
        String createBody = """
            {
              "nameEn": "Pants_%d",
              "nameBn": "প্যান্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Waist",
                  "nameBn": "ওয়েস্ট",
                  "unit": "inches",
                  "type": "NUMERIC",
                  "nsId": "AB12"
                }
              ]
            }
            """.formatted(System.currentTimeMillis());
        Response createRes = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(createBody).when().post("/api/items").then().statusCode(200).extract().response();
        Number itemIdNum = createRes.path("data.id");
        Assert.assertNotNull(itemIdNum, "Created item ID should not be null");
        Long itemId = itemIdNum.longValue();
        // Update item with parameter 'Waist', unit 'cm', retaining nsId 'AB12'
        String updateBody = """
            {
              "nameEn": "Pants_Updated",
              "nameBn": "প্যান্ট",
              "status": "ACTIVE",
              "parameters": [
                {
                  "nameEn": "Waist",
                  "nameBn": "ওয়েস্ট",
                  "unit": "cm",
                  "type": "NUMERIC",
                  "nsId": "AB12"
                }
              ]
            }
            """;
        Response updateRes = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(updateBody).when().put("/api/items/{id}", itemId).then().statusCode(200).extract().response();
        String updatedNsId = updateRes.path("data.parameters[0].nsId");
        String updatedUnit = updateRes.path("data.parameters[0].unit");
        Assert.assertEquals(updatedUnit, "cm", "Parameter unit should be updated to cm");
        Assert.assertEquals(updatedNsId, "AB12", "Parameter nsId should be preserved as AB12");
    }

