    private String obtainShopOwnerToken() {
        if (ownerToken != null) {
            return ownerToken;
        }
        long ts = System.currentTimeMillis();
        String email = "owner_dash_" + ts + "@example.com";
        String phone = "017" + String.format("%08d", (int) (ts % 100000000L));
        // 1. Create Area (Admin)
        String areaBody = """
            {
              "name": "Dash Area %d"
            }
            """.formatted(ts);
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Long areaId = areaResp.path("data.id") != null ? ((Number) areaResp.path("data.id")).longValue() : ((Number) areaResp.path("id")).longValue();
        // 2. Create Shop (Admin)
        String shopBody = """
            {
              "shopName": "Dash Shop %d",
              "shopPhone": "%s",
              "ownerName": "Owner %d",
              "email": "%s",
              "address": "Test Address",
              "areaId": %d,
              "status": true
            }
            """.formatted(ts, phone, ts, email, areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        // 3. Request OTP
        Response otpResp = given().queryParam("email", email).when().post("/api/auth/request-otp").then().statusCode(200).extract().response();
        String otp = otpResp.path("data");
        // 4. Verify OTP & Set PIN
        String setPinBody = """
            {
              "phoneNumber": "%s",
              "otp": "%s",
              "pin": "1234",
              "confirmPin": "1234"
            }
            """.formatted(phone, otp);
        given().contentType(ContentType.JSON).body(setPinBody).when().post("/api/auth/set-pin").then().statusCode(200);
        // 5. Login as Shop Owner
        String loginBody = """
            {
              "username": "%s",
              "pin": "1234"
            }
            """.formatted(phone);
        Response loginResp = given().contentType(ContentType.JSON).body(loginBody).when().post("/api/auth/login").then().statusCode(200).extract().response();
        String hVal = loginResp.getHeader("Authorization");
        if (hVal != null && hVal.startsWith("Bearer ")) {
            ownerToken = hVal.substring(7);
        } else {
            ownerToken = loginResp.path("data.accessToken");
        }
        return ownerToken;
    }

