    private List<Long> createdOrderIds = new ArrayList<>();

    private Long createOrderHelper(String orderDate, String deliveryDate, String phoneSuffix) {
        long ts = System.currentTimeMillis();
        String phone = "018" + String.format("%08d", (ts + (long) (Math.random() * 1000)) % 100000000L);
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer_%s",
              "customerPhone": "%s",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "%s",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "None",
                      "clothPhoto": "http://minio/temp/cloth_%d.jpg",
                      "deliveryDate": "%s",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopId, phoneSuffix, phone, deliveryDate, itemId, ts, deliveryDate);
        Response res = given().header("Authorization", "Bearer " + ownerToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(anyOf(is(200), is(201))).extract().response();
        Long id = res.path("data.id") != null ? ((Number) res.path("data.id")).longValue() : ((Number) res.path("id")).longValue();
        createdOrderIds.add(id);
        return id;
    }

    // ab7954e-TC-007
    @Test
    public void verifyMonthlyOrdersBoundary() {
        YearMonth currentMonth = YearMonth.now();
        LocalDate lastDayPrevMonth = currentMonth.minusMonths(1).atEndOfMonth();
        LocalDate firstDayCurrMonth = currentMonth.atDay(1);
        LocalDate lastDayCurrMonth = currentMonth.atEndOfMonth();
        // Preconditions: Order A (last day prev month), Order B (1st day curr month), Order C (last day curr month)
        Long orderA = createOrderHelper(lastDayPrevMonth.toString(), lastDayPrevMonth.toString(), "A");
        Long orderB = createOrderHelper(firstDayCurrMonth.toString(), firstDayCurrMonth.toString(), "B");
        Long orderC = createOrderHelper(lastDayCurrMonth.toString(), lastDayCurrMonth.toString(), "C");
        Response response = given().header("Authorization", "Bearer " + ownerToken).queryParam("page", 0).queryParam("limit", 50).when().get("/api/dashboard/orders/monthly").then().statusCode(200).body("status", equalTo("success")).extract().response();
        List<Integer> returnedIds = response.path("data.content.id");
        Assert.assertNotNull(returnedIds, "Monthly orders content should not be null");
        Assert.assertTrue(returnedIds.contains(orderB.intValue()), "Monthly orders must include Order B (1st day of current month)");
        Assert.assertTrue(returnedIds.contains(orderC.intValue()), "Monthly orders must include Order C (last day of current month)");
        Assert.assertFalse(returnedIds.contains(orderA.intValue()), "Monthly orders must exclude Order A (previous month)");
    }

    // ab7954e-TC-008
    @Test
    public void verifyOverdueOrdersBoundary() {
        LocalDate yesterday = LocalDate.now().minusDays(1);
        LocalDate today = LocalDate.now();
        // Order 101: delivery date yesterday
        Long order101 = createOrderHelper(yesterday.toString(), yesterday.toString(), "101");
        // Order 102: delivery date today
        Long order102 = createOrderHelper(today.toString(), today.toString(), "102");
        Response response = given().header("Authorization", "Bearer " + ownerToken).queryParam("page", 0).queryParam("limit", 50).when().get("/api/dashboard/orders/overdue").then().statusCode(200).body("status", equalTo("success")).extract().response();
        List<Integer> returnedIds = response.path("data.content.id");
        Assert.assertNotNull(returnedIds, "Overdue orders content should not be null");
        Assert.assertTrue(returnedIds.contains(order101.intValue()), "Overdue orders must contain Order 101 (delivery date yesterday)");
        Assert.assertFalse(returnedIds.contains(order102.intValue()), "Overdue orders must not contain Order 102 (delivery date today)");
    }

