    private Response createOrderWithItems(Long shopId, Long itemId, int numberOfItems) {
        StringBuilder itemsJson = new StringBuilder();
        for (int i = 0; i < numberOfItems; i++) {
            if (i > 0)
                itemsJson.append(",");
            itemsJson.append("""
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "specialInstruction": "Standard fit",
                      "clothPhoto": "temp-cloth.jpg",
                      "deliveryDate": "2028-12-31",
                      "makingCharge": 500.00,
                      "measurements": []
                    }
                  ]
                }
                """.formatted(itemId));
        }
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "John Doe",
              "customerPhone": "+88017%08d",
              "customerGender": "MALE",
              "paidAmount": 100.00,
              "deliveryDate": "2028-12-31",
              "items": [%s]
            }
            """.formatted(shopId, (int) (Math.random() * 100000000), itemsJson.toString());
        return given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders");
    }

