    // f3246cb-TC-004
    @Test
    public void parentOrderStatusBecomesInProgressWhenSubsetReadyForDelivery() {
        Long areaId = createArea38();
        Long shopId = createShop34(areaId);
        Long itemId = createItem44();
        Response orderResp = createOrderWithItems(shopId, itemId, 2).then().statusCode(200).extract().response();
        Integer item1IdInt = orderResp.path("data.orderItems[0].id");
        Integer item2IdInt = orderResp.path("data.orderItems[1].id");
        Assert.assertNotNull(item1IdInt, "Item 1 ID is null");
        Assert.assertNotNull(item2IdInt, "Item 2 ID is null");
        Long item1Id = item1IdInt.longValue();
        Long item2Id = item2IdInt.longValue();
        // Transition Item 1 to CUTTING_DONE
        given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"CUTTING_DONE\"}").when().put("/api/orders/items/{orderItemId}/status", item1Id).then().statusCode(200);
        // Transition Item 2 step by step: MEASUREMENT_DONE -> CUTTING_DONE -> SEWING_DONE -> PRESS_DONE -> READY_FOR_DELIVERY
        String[] transitions = { "CUTTING_DONE", "SEWING_DONE", "PRESS_DONE", "READY_FOR_DELIVERY" };
        for (String nextStatus : transitions) {
            given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"" + nextStatus + "\"}").when().put("/api/orders/items/{orderItemId}/status", item2Id).then().statusCode(200).body("status", equalTo("success"));
        }
    }

    // f3246cb-TC-005
    @Test
    public void parentOrderStatusBecomesDeliveredWhenAllItemsDelivered() {
        Long areaId = createArea38();
        Long shopId = createShop34(areaId);
        Long itemId = createItem44();
        Response orderResp = createOrderWithItems(shopId, itemId, 2).then().statusCode(200).extract().response();
        Integer item1IdInt = orderResp.path("data.orderItems[0].id");
        Integer item2IdInt = orderResp.path("data.orderItems[1].id");
        Assert.assertNotNull(item1IdInt, "Item 1 ID is null");
        Assert.assertNotNull(item2IdInt, "Item 2 ID is null");
        Long item1Id = item1IdInt.longValue();
        Long item2Id = item2IdInt.longValue();
        String[] fullSequence = { "CUTTING_DONE", "SEWING_DONE", "PRESS_DONE", "READY_FOR_DELIVERY", "DELIVERED" };
        for (String nextStatus : fullSequence) {
            given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"" + nextStatus + "\"}").when().put("/api/orders/items/{orderItemId}/status", item1Id).then().statusCode(200);
        }
        for (String nextStatus : fullSequence) {
            Response updateResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body("{\"newStatus\": \"" + nextStatus + "\"}").when().put("/api/orders/items/{orderItemId}/status", item2Id).then().statusCode(200).extract().response();
            Assert.assertEquals(updateResp.path("status"), "success");
        }
    }

