    // b03ab1a-TC-001 - Process partial payment for an order and verify updated balance
    @Test
    public void processPartialPaymentForOrderAndVerifyUpdatedBalance() {
        Long areaId = createArea39();
        Long shopId = createShop35(areaId);
        Long itemId = createItem45();
        Long orderId = createOrderFixture(shopId, itemId, 1000.00, 200.00);
        String paymentBody = """
            {
              "paymentAmount": 300.00
            }
            """;
        Response payResponse = given().header("Authorization", adminToken).contentType(ContentType.JSON).body(paymentBody).when().post("/api/orders/{orderId}/pay", orderId).then().statusCode(200).extract().response();
        Number totalAmount = payResponse.path("totalAmount");
        Number paidAmount = payResponse.path("paidAmount");
        Number dueAmount = payResponse.path("dueAmount");
        Assert.assertNotNull(totalAmount, "totalAmount should not be null");
        Assert.assertNotNull(paidAmount, "paidAmount should not be null");
        Assert.assertNotNull(dueAmount, "dueAmount should not be null");
        Assert.assertEquals(totalAmount.doubleValue(), 1000.00, 0.01, "Total amount should be 1000.00");
        Assert.assertEquals(paidAmount.doubleValue(), 500.00, 0.01, "Paid amount should be 500.00");
        Assert.assertEquals(dueAmount.doubleValue(), 500.00, 0.01, "Due amount should be 500.00");
    }

