    // b03ab1a-TC-012
    @Test
    public void verifyPaymentResponseDoesNotExposeFinancialDataOfOtherShopsInErrorScenarios() {
        // 1. Create Area for Shop B
        String areaBody = """
            {
              "name": "Area_%d"
            }
            """.formatted(System.currentTimeMillis());
        Response areaResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(areaBody).when().post("/api/areas").then().statusCode(200).extract().response();
        Long areaId = areaResp.path("data.id");
        // 2. Create Shop B
        String shopBody = """
            {
              "shopName": "ShopB_%d",
              "shopPhone": "017%08d",
              "ownerName": "OwnerB",
              "email": "ownerB_%d@example.com",
              "address": "Address B",
              "areaId": %d,
              "status": true
            }
            """.formatted(System.currentTimeMillis(), System.currentTimeMillis() % 100000000L, System.currentTimeMillis(), areaId);
        Response shopResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(shopBody).when().post("/api/areas/" + areaId + "/shops").then().statusCode(200).extract().response();
        Long shopBId = shopResp.path("id");
        // 3. Create Item
        String itemBody = """
            {
              "nameEn": "Shirt_%d",
              "nameBn": "শার্ট",
              "status": "ACTIVE",
              "parameters": []
            }
            """.formatted(System.currentTimeMillis());
        Response itemResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(itemBody).when().post("/api/items").then().statusCode(200).extract().response();
        Long itemId = itemResp.path("data.id");
        // 4. Create Order for Shop B using Admin token (Admin can bypass or create order)
        String orderBody = """
            {
              "shopId": %d,
              "customerName": "Customer B",
              "customerPhone": "01712345678",
              "customerGender": "MALE",
              "paidAmount": 0,
              "deliveryDate": "2026-12-31",
              "items": [
                {
                  "itemId": %d,
                  "measurementGroups": [
                    {
                      "clothPhoto": "temp/photo.jpg",
                      "makingCharge": 500,
                      "measurements": []
                    }
                  ]
                }
              ]
            }
            """.formatted(shopBId, itemId);
        Response orderResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(orderBody).when().post("/api/orders").then().statusCode(200).extract().response();
        Long orderBId = orderResp.path("data.id");
        Assert.assertNotNull(orderBId, "Precondition failed: Shop B order creation failed");
        // 5. Attempt payment on Shop B's order using Admin token or another shop's token
        // Request payload
        String payBody = """
            {
              "paymentAmount": 1000.00
            }
            """;
        // Admin is not the owner of Shop B, so attempt payment with Admin token or non-owner
        Response payResp = given().header("Authorization", "Bearer " + adminToken).contentType(ContentType.JSON).body(payBody).when().post("/api/orders/" + orderBId + "/pay").then().statusCode(anyOf(is(403), is(404), is(401))).extract().response();
        String bodyStr = payResp.asString();
        Assert.assertFalse(bodyStr.contains("totalAmount"), "Financial data totalAmount exposed in response: " + bodyStr);
        Assert.assertFalse(bodyStr.contains("dueAmount"), "Financial data dueAmount exposed in response: " + bodyStr);
    }

